import type { Request, Response, NextFunction } from 'express';
import { verifyAccessToken, verifyRefreshToken, type TokenPayload } from '../services/authService.js';
import { UnauthorizedError } from '../utils/errors.js';
import jwt from 'jsonwebtoken';
import { config } from '../config/index.js';

declare global {
  namespace Express {
    interface Request {
      user?: TokenPayload;
    }
  }
}

export function requireAuth(req: Request, _res: Response, next: NextFunction): void {
  const accessToken = req.cookies?.accessToken;

  if (!accessToken) {
    next(new UnauthorizedError('Authentication required'));
    return;
  }

  try {
    const payload = verifyAccessToken(accessToken);
    req.user = payload;
    next();
  } catch {
    next(new UnauthorizedError('Invalid or expired token'));
  }
}

export function setTokenCookies(
  res: Response,
  accessToken: string,
  refreshToken: string
): void {
  res.cookie('accessToken', accessToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 15 * 60 * 1000, // 15 minutes
  });

  res.cookie('refreshToken', refreshToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
  });
}

export function clearTokenCookies(res: Response): void {
  res.clearCookie('accessToken');
  res.clearCookie('refreshToken');
}

import { Router } from 'express';
import { validate } from '../middleware/validate.js';
import { registerSchema, loginSchema } from '../types/schemas.js';
import * as authService from '../services/authService.js';
import { setTokenCookies, clearTokenCookies } from '../middleware/auth.js';
import { UnauthorizedError } from '../utils/errors.js';

const router = Router();

router.post('/register', validate(registerSchema), async (req, res, next) => {
  try {
    const result = await authService.register(req.body);
    setTokenCookies(res, result.accessToken, result.refreshToken);
    res.status(201).json({ data: result.user });
  } catch (err) {
    next(err);
  }
});

router.post('/login', validate(loginSchema), async (req, res, next) => {
  try {
    const result = await authService.login(req.body);
    setTokenCookies(res, result.accessToken, result.refreshToken);
    res.json({ data: result.user });
  } catch (err) {
    next(err);
  }
});

router.post('/logout', (_req, res) => {
  clearTokenCookies(res);
  res.json({ data: { message: 'Logged out successfully' } });
});

router.post('/refresh', async (req, res, next) => {
  try {
    const refreshToken = req.cookies?.refreshToken;
    if (!refreshToken) {
      throw new UnauthorizedError('No refresh token provided');
    }
    const tokens = await authService.refreshTokens(refreshToken);
    setTokenCookies(res, tokens.accessToken, tokens.refreshToken);
    res.json({ data: { message: 'Tokens refreshed' } });
  } catch (err) {
    next(err);
  }
});

export default router;

