import { PrismaClient } from '@prisma/client';
import { ConflictError, NotFoundError } from '../utils/errors.js';
import type { UpdateProfileInput } from '../types/schemas.js';

const prisma = new PrismaClient();

export async function getProfile(userId: string) {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      id: true,
      email: true,
      displayName: true,
      paypalLink: true,
      createdAt: true,
    },
  });

  if (!user) {
    throw new NotFoundError('User not found');
  }

  return user;
}

export async function updateProfile(userId: string, input: UpdateProfileInput) {
  if (input.email) {
    const existing = await prisma.user.findFirst({
      where: { email: input.email, NOT: { id: userId } },
    });
    if (existing) {
      throw new ConflictError('Email already in use');
    }
  }

  const user = await prisma.user.update({
    where: { id: userId },
    data: {
      ...(input.displayName !== undefined && { displayName: input.displayName }),
      ...(input.email !== undefined && { email: input.email }),
      ...(input.paypalLink !== undefined && { paypalLink: input.paypalLink }),
    },
    select: {
      id: true,
      email: true,
      displayName: true,
      paypalLink: true,
    },
  });

  return user;
}

export async function deleteAccount(userId: string) {
  await prisma.user.delete({
    where: { id: userId },
  });
}

import { Router } from 'express';
import { requireAuth } from '../middleware/auth.js';
import { validate } from '../middleware/validate.js';
import { updateProfileSchema } from '../types/schemas.js';
import * as userService from '../services/userService.js';
import { clearTokenCookies } from '../middleware/auth.js';

const router = Router();

router.get('/me', requireAuth, async (req, res, next) => {
  try {
    const user = await userService.getProfile(req.user!.userId);
    res.json({ data: user });
  } catch (err) {
    next(err);
  }
});

router.patch('/me', requireAuth, validate(updateProfileSchema), async (req, res, next) => {
  try {
    const user = await userService.updateProfile(req.user!.userId, req.body);
    res.json({ data: user });
  } catch (err) {
    next(err);
  }
});

router.delete('/me', requireAuth, async (req, res, next) => {
  try {
    await userService.deleteAccount(req.user!.userId);
    clearTokenCookies(res);
    res.json({ data: { message: 'Account deleted successfully' } });
  } catch (err) {
    next(err);
  }
});

