const API_BASE = '/api/v1';

interface FetchOptions extends RequestInit {
  body?: string;
}

export async function apiFetch<T>(
  path: string,
  options: FetchOptions = {}
): Promise<T> {
  const res = await fetch(`${API_BASE}${path}`, {
    ...options,
    credentials: 'include',
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });

  const json = await res.json();

  if (!res.ok) {
    const errorMessage = json.error?.message || 'An error occurred';
    throw new ApiError(res.status, json.error?.code || 'UNKNOWN', errorMessage, json.error?.details);
  }

  return json.data;
}

export class ApiError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public details?: Array<{ field: string; message: string }>
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

import { useState, useCallback } from 'react';
import { apiFetch, ApiError } from '../utils/api';

interface UseApiState<T> {
  data: T | null;
  error: ApiError | null;
  loading: boolean;
}

export function useApi<T>() {
  const [state, setState] = useState<UseApiState<T>>({
    data: null,
    error: null,
    loading: false,
  });

  const execute = useCallback(
    async (path: string, options?: RequestInit): Promise<T | null> => {
      setState({ data: null, error: null, loading: true });
      try {
        const data = await apiFetch<T>(path, options);
        setState({ data, error: null, loading: false });
        return data;
      } catch (err) {
        const apiError =
          err instanceof ApiError
            ? err
            : new ApiError(500, 'UNKNOWN', (err as Error).message);
        setState({ data: null, error: apiError, loading: false });
        return null;
      }
    },
    []
  );

  return { ...state, execute };
}

