import { BrowserRouter, Routes, Route, Navigate, Link, Outlet } from 'react-router-dom';
import { AuthProvider, useAuth } from './features/auth/AuthContext';
import LoginPage from './features/auth/LoginPage';
import RegisterPage from './features/auth/RegisterPage';
import ProfilePage from './features/profile/ProfilePage';

function Layout() {
  const { user, logout } = useAuth();

  return (
    <div className="min-h-screen bg-gray-50">
      <nav className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-14 items-center">
            <Link to="/" className="text-lg font-bold text-gray-900">
              Cost Splitting
            </Link>
            {user && (
              <div className="flex items-center gap-4">
                <Link to="/groups" className="text-sm text-gray-600 hover:text-gray-900">
                  Groups
                </Link>
                <Link to="/profile" className="text-sm text-gray-600 hover:text-gray-900">
                  Profile
                </Link>
                <button
                  onClick={() => logout()}
                  className="text-sm text-gray-600 hover:text-gray-900"
                >
                  Log Out
                </button>
              </div>
            )}
          </div>
        </div>
      </nav>
      <Outlet />
    </div>
  );
}

function RequireAuth({ children }: { children: React.ReactNode }) {
  const { user, loading } = useAuth();
  if (loading) return null;
  if (!user) return <Navigate to="/login" replace />;
  return <>{children}</>;
}

function RedirectIfAuth({ children }: { children: React.ReactNode }) {
  const { user, loading } = useAuth();
  if (loading) return null;
  if (user) return <Navigate to="/groups" replace />;
  return <>{children}</>;
}

function GroupsPlaceholder() {
  return (
    <div className="max-w-4xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-gray-900 mb-4">Groups</h1>
      <p className="text-gray-600">No groups yet. Create one to get started.</p>
    </div>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <Routes>
          <Route element={<Layout />}>
            <Route
              path="/login"
              element={<RedirectIfAuth><LoginPage /></RedirectIfAuth>}
            />
            <Route
              path="/register"
              element={<RedirectIfAuth><RegisterPage /></RedirectIfAuth>}
            />
            <Route
              path="/profile"
              element={<RequireAuth><ProfilePage /></RequireAuth>}
            />
            <Route
              path="/groups"
              element={<RequireAuth><GroupsPlaceholder /></RequireAuth>}
            />
            <Route path="/" element={<Navigate to="/groups" replace />} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Route>
        </Routes>
      </AuthProvider>
    </BrowserRouter>
  );
}

