import { PrismaClient } from '@prisma/client';
import { ConflictError, ForbiddenError, NotFoundError } from '../utils/errors.js';

const prisma = new PrismaClient();

export async function createGroup(userId: string, name: string) {
  const group = await prisma.group.create({
    data: {
      name,
      members: {
        create: { userId },
      },
    },
    include: {
      members: {
        include: { user: { select: { id: true, displayName: true, email: true } } },
      },
    },
  });
  return group;
}

export async function listGroups(userId: string) {
  const groups = await prisma.group.findMany({
    where: {
      archived: false,
      members: { some: { userId } },
    },
    include: {
      _count: { select: { members: true } },
    },
    orderBy: { createdAt: 'desc' },
  });
  return groups;
}

export async function getGroup(userId: string, groupId: string) {
  const group = await prisma.group.findUnique({
    where: { id: groupId },
    include: {
      members: {
        include: { user: { select: { id: true, displayName: true, email: true, paypalLink: true } } },
      },
    },
  });

  if (!group) {
    throw new NotFoundError('Group not found');
  }

  const isMember = group.members.some((m) => m.userId === userId);
  if (!isMember) {
    throw new ForbiddenError('You are not a member of this group');
  }

  return group;
}

export async function updateGroup(userId: string, groupId: string, name: string) {
  await assertMembership(userId, groupId);

  const group = await prisma.group.update({
    where: { id: groupId },
    data: { name },
  });
  return group;
}

export async function archiveGroup(userId: string, groupId: string) {
  await assertMembership(userId, groupId);

  const group = await prisma.group.update({
    where: { id: groupId },
    data: { archived: true },
  });
  return group;
}

export async function inviteMember(userId: string, groupId: string, email: string) {
  await assertMembership(userId, groupId);

  // Check if already a member
  const existingMember = await prisma.groupMember.findFirst({
    where: {
      groupId,
      user: { email },
    },
  });
  if (existingMember) {
    throw new ConflictError('User is already a member of this group');
  }

  // Check for pending invitation
  const existingInvite = await prisma.invitation.findFirst({
    where: {
      groupId,
      email,
      status: 'PENDING',
    },
  });
  if (existingInvite) {
    throw new ConflictError('An invitation is already pending for this email');
  }

  // Find recipient user if they exist
  const recipientUser = await prisma.user.findUnique({ where: { email } });

  const invitation = await prisma.$transaction(async (tx) => {
    const invite = await tx.invitation.create({
      data: {
        groupId,
        email,
        senderId: userId,
        recipientId: recipientUser?.id ?? null,
      },
    });

    // Create in-app notification if the user exists
    if (recipientUser) {
      const group = await tx.group.findUnique({ where: { id: groupId } });
      const sender = await tx.user.findUnique({ where: { id: userId } });
      await tx.notification.create({
        data: {
          userId: recipientUser.id,
          type: 'GROUP_INVITATION',
          data: {
            invitationId: invite.id,
            groupId,
            groupName: group!.name,
            invitedBy: sender!.displayName,
          },
        },
      });
    }

    return invite;
  });

  return invitation;
}

export async function listInvitations(userId: string) {
  const invitations = await prisma.invitation.findMany({
    where: {
      recipientId: userId,
      status: 'PENDING',
    },
    include: {
      group: { select: { id: true, name: true } },
      sender: { select: { id: true, displayName: true } },
    },
    orderBy: { createdAt: 'desc' },
  });
  return invitations;
}

export async function respondToInvitation(userId: string, invitationId: string, accept: boolean) {
  const invitation = await prisma.invitation.findUnique({
    where: { id: invitationId },
  });

  if (!invitation || invitation.recipientId !== userId) {
    throw new NotFoundError('Invitation not found');
  }

  if (invitation.status !== 'PENDING') {
    throw new ConflictError('Invitation has already been responded to');
  }

  if (accept) {
    await prisma.$transaction(async (tx) => {
      await tx.invitation.update({
        where: { id: invitationId },
        data: { status: 'ACCEPTED' },
      });
      await tx.groupMember.create({
        data: {
          userId,
          groupId: invitation.groupId,
        },
      });
    });
  } else {
    await prisma.invitation.update({
      where: { id: invitationId },
      data: { status: 'DECLINED' },
    });
  }
}

export async function getGroupMembers(userId: string, groupId: string) {
  await assertMembership(userId, groupId);

  const members = await prisma.groupMember.findMany({
    where: { groupId },
    include: {
      user: { select: { id: true, displayName: true, email: true, paypalLink: true } },
    },
  });
  return members;
}

async function assertMembership(userId: string, groupId: string) {
  const membership = await prisma.groupMember.findUnique({
    where: { userId_groupId: { userId, groupId } },
  });
  if (!membership) {
    throw new ForbiddenError('You are not a member of this group');
  }
}

export { assertMembership };

import { Router } from 'express';
import { requireAuth } from '../middleware/auth.js';
import { validate } from '../middleware/validate.js';
import { createGroupSchema, updateGroupSchema, inviteMemberSchema, respondInvitationSchema } from '../types/schemas.js';
import * as groupService from '../services/groupService.js';

const router = Router();

// Groups CRUD
router.post('/', requireAuth, validate(createGroupSchema), async (req, res, next) => {
  try {
    const group = await groupService.createGroup(req.user!.userId, req.body.name);
    res.status(201).json({ data: group });
  } catch (err) {
    next(err);
  }
});

router.get('/', requireAuth, async (req, res, next) => {
  try {
    const groups = await groupService.listGroups(req.user!.userId);
    res.json({ data: groups });
  } catch (err) {
    next(err);
  }
});

router.get('/:groupId', requireAuth, async (req, res, next) => {
  try {
    const group = await groupService.getGroup(req.user!.userId, req.params.groupId);
    res.json({ data: group });
  } catch (err) {
    next(err);
  }
});

router.patch('/:groupId', requireAuth, validate(updateGroupSchema), async (req, res, next) => {
  try {
    const group = await groupService.updateGroup(req.user!.userId, req.params.groupId, req.body.name);
    res.json({ data: group });
  } catch (err) {
    next(err);
  }
});

router.post('/:groupId/archive', requireAuth, async (req, res, next) => {
  try {
    const group = await groupService.archiveGroup(req.user!.userId, req.params.groupId);
    res.json({ data: group });
  } catch (err) {
    next(err);
  }
});

// Members
router.get('/:groupId/members', requireAuth, async (req, res, next) => {
  try {
    const members = await groupService.getGroupMembers(req.user!.userId, req.params.groupId);
    res.json({ data: members });
  } catch (err) {
    next(err);
  }
});

// Invitations
router.post('/:groupId/invitations', requireAuth, validate(inviteMemberSchema), async (req, res, next) => {
  try {
    const invitation = await groupService.inviteMember(req.user!.userId, req.params.groupId, req.body.email);
    res.status(201).json({ data: invitation });
  } catch (err) {
    next(err);
  }
});

// User invitations
router.get('/invitations/mine', requireAuth, async (req, res, next) => {
  try {
    const invitations = await groupService.listInvitations(req.user!.userId);
    res.json({ data: invitations });
  } catch (err) {
    next(err);
  }
});

router.post('/invitations/:invitationId/respond', requireAuth, validate(respondInvitationSchema), async (req, res, next) => {
  try {
    await groupService.respondToInvitation(req.user!.userId, req.params.invitationId, req.body.accept);
    res.json({ data: { message: req.body.accept ? 'Invitation accepted' : 'Invitation declined' } });
  } catch (err) {
    next(err);
  }
});

export default router;

