import { useState, useEffect, type FormEvent } from 'react';
import { Link } from 'react-router-dom';
import { apiFetch, ApiError } from '../../utils/api';

interface Group {
  id: string;
  name: string;
  _count: { members: number };
}

export default function GroupsListPage() {
  const [groups, setGroups] = useState<Group[]>([]);
  const [loading, setLoading] = useState(true);
  const [newGroupName, setNewGroupName] = useState('');
  const [creating, setCreating] = useState(false);
  const [showCreate, setShowCreate] = useState(false);
  const [error, setError] = useState('');

  const loadGroups = async () => {
    try {
      const data = await apiFetch<Group[]>('/groups');
      setGroups(data);
    } catch {
      setError('Failed to load groups');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadGroups();
  }, []);

  const handleCreate = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setCreating(true);
    try {
      await apiFetch('/groups', {
        method: 'POST',
        body: JSON.stringify({ name: newGroupName }),
      });
      setNewGroupName('');
      setShowCreate(false);
      await loadGroups();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to create group');
    } finally {
      setCreating(false);
    }
  };

  if (loading) {
    return <div className="max-w-4xl mx-auto p-6">Loading...</div>;
  }

  return (
    <div className="max-w-4xl mx-auto p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-900">Groups</h1>
        <button
          onClick={() => setShowCreate(!showCreate)}
          className="py-2 px-4 rounded-md text-sm font-medium text-white bg-blue-600 hover:bg-blue-700"
        >
          Create Group
        </button>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded mb-4" role="alert">
          {error}
        </div>
      )}

      {showCreate && (
        <form onSubmit={handleCreate} className="bg-white p-4 rounded-lg shadow mb-6 flex gap-3">
          <input
            type="text"
            value={newGroupName}
            onChange={(e) => setNewGroupName(e.target.value)}
            placeholder="Group name"
            required
            className="flex-1 rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
          />
          <button
            type="submit"
            disabled={creating}
            className="py-2 px-4 rounded-md text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 disabled:opacity-50"
          >
            {creating ? 'Creating...' : 'Create'}
          </button>
        </form>
      )}

      {groups.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-lg shadow">
          <p className="text-gray-600">No groups yet. Create one to get started.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {groups.map((group) => (
            <Link
              key={group.id}
              to={`/groups/${group.id}`}
              className="block bg-white p-4 rounded-lg shadow hover:shadow-md transition-shadow"
            >
              <div className="flex justify-between items-center">
                <h3 className="font-semibold text-gray-900">{group.name}</h3>
                <span className="text-sm text-gray-500">{group._count.members} member{group._count.members !== 1 ? 's' : ''}</span>
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, type FormEvent } from 'react';
import { useParams, Link } from 'react-router-dom';
import { apiFetch, ApiError } from '../../utils/api';

interface Member {
  id: string;
  user: { id: string; displayName: string; email: string; paypalLink: string | null };
}

interface Group {
  id: string;
  name: string;
  archived: boolean;
  members: Member[];
}

export default function GroupDetailPage() {
  const { groupId } = useParams<{ groupId: string }>();
  const [group, setGroup] = useState<Group | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviting, setInviting] = useState(false);
  const [editingName, setEditingName] = useState(false);
  const [newName, setNewName] = useState('');
  const [success, setSuccess] = useState('');

  const loadGroup = async () => {
    try {
      const data = await apiFetch<Group>(`/groups/${groupId}`);
      setGroup(data);
      setNewName(data.name);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to load group');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadGroup();
  }, [groupId]);

  const handleInvite = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setInviting(true);
    try {
      await apiFetch(`/groups/${groupId}/invitations`, {
        method: 'POST',
        body: JSON.stringify({ email: inviteEmail }),
      });
      setInviteEmail('');
      setSuccess('Invitation sent');
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to send invitation');
    } finally {
      setInviting(false);
    }
  };

  const handleRename = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    try {
      await apiFetch(`/groups/${groupId}`, {
        method: 'PATCH',
        body: JSON.stringify({ name: newName }),
      });
      setEditingName(false);
      await loadGroup();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to rename group');
    }
  };

  const handleArchive = async () => {
    setError('');
    try {
      await apiFetch(`/groups/${groupId}/archive`, { method: 'POST' });
      window.location.href = '/groups';
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to archive group');
    }
  };

  if (loading) return <div className="max-w-4xl mx-auto p-6">Loading...</div>;
  if (!group) return <div className="max-w-4xl mx-auto p-6">Group not found</div>;

  return (
    <div className="max-w-4xl mx-auto p-6">
      <Link to="/groups" className="text-blue-600 hover:text-blue-500 text-sm mb-4 inline-block">&larr; Back to Groups</Link>

      <div className="flex justify-between items-center mb-6">
        {editingName ? (
          <form onSubmit={handleRename} className="flex gap-2">
            <input
              type="text"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              required
              className="rounded-md border border-gray-300 px-3 py-1 text-lg font-bold"
            />
            <button type="submit" className="text-sm text-blue-600 hover:text-blue-500">Save</button>
            <button type="button" onClick={() => setEditingName(false)} className="text-sm text-gray-500">Cancel</button>
          </form>
        ) : (
          <h1 className="text-2xl font-bold text-gray-900">
            {group.name}
            <button onClick={() => setEditingName(true)} className="ml-2 text-sm text-gray-400 hover:text-gray-600">Edit</button>
          </h1>
        )}
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded mb-4" role="alert">{error}</div>
      )}
      {success && (
        <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded mb-4">{success}</div>
      )}

      {/* Navigation tabs */}
      <div className="flex gap-4 mb-6 border-b border-gray-200 pb-2">
        <Link to={`/groups/${groupId}`} className="text-sm font-medium text-blue-600">Members</Link>
        <Link to={`/groups/${groupId}/expenses`} className="text-sm font-medium text-gray-500 hover:text-gray-700">Expenses</Link>
        <Link to={`/groups/${groupId}/balances`} className="text-sm font-medium text-gray-500 hover:text-gray-700">Balances</Link>
        <Link to={`/groups/${groupId}/settlements`} className="text-sm font-medium text-gray-500 hover:text-gray-700">Settlements</Link>
      </div>

      {/* Members */}
      <div className="bg-white p-6 rounded-lg shadow mb-6">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Members ({group.members.length})</h2>
        <ul className="divide-y divide-gray-100">
          {group.members.map((m) => (
            <li key={m.id} className="py-3 flex justify-between items-center">
              <div>
                <p className="font-medium text-gray-900">{m.user.displayName}</p>
                <p className="text-sm text-gray-500">{m.user.email}</p>
              </div>
              {m.user.paypalLink && (
                <a href={m.user.paypalLink} target="_blank" rel="noopener noreferrer" className="text-sm text-blue-600 hover:text-blue-500">
                  PayPal
                </a>
              )}
            </li>
          ))}
        </ul>
      </div>

      {/* Invite */}
      <div className="bg-white p-6 rounded-lg shadow mb-6">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Invite Member</h2>
        <form onSubmit={handleInvite} className="flex gap-3">
          <input
            type="email"
            value={inviteEmail}
            onChange={(e) => setInviteEmail(e.target.value)}
            placeholder="Email address"
            required
            className="flex-1 rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
          />
          <button
            type="submit"
            disabled={inviting}
            className="py-2 px-4 rounded-md text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 disabled:opacity-50"
          >
            {inviting ? 'Inviting...' : 'Invite'}
          </button>
        </form>
      </div>

      {/* Danger zone */}
      <div className="bg-white p-6 rounded-lg shadow border border-red-200">
        <h2 className="text-lg font-semibold text-red-600 mb-4">Danger Zone</h2>
        <button
          onClick={handleArchive}
