import { ValidationError } from './errors.js';

export interface SplitParticipant {
  userId: string;
  percentage?: number;
  amountCents?: number;
}

export function splitEqual(totalCents: number, participants: SplitParticipant[]): Map<string, number> {
  const count = participants.length;
  const baseCents = Math.floor(totalCents / count);
  const remainder = totalCents - baseCents * count;

  const result = new Map<string, number>();
  participants.forEach((p, i) => {
    result.set(p.userId, baseCents + (i < remainder ? 1 : 0));
  });
  return result;
}

export function splitPercentage(totalCents: number, participants: SplitParticipant[]): Map<string, number> {
  const totalPct = participants.reduce((sum, p) => sum + (p.percentage ?? 0), 0);
  if (Math.abs(totalPct - 100) > 0.01) {
    throw new ValidationError('Percentages must sum to 100%');
  }

  const result = new Map<string, number>();
  let allocated = 0;

  participants.forEach((p, i) => {
    if (i === participants.length - 1) {
      // Last participant gets the remainder to ensure exact total
      result.set(p.userId, totalCents - allocated);
    } else {
      const share = Math.round((totalCents * (p.percentage ?? 0)) / 100);
      result.set(p.userId, share);
      allocated += share;
    }
  });

  return result;
}

export function splitFixed(totalCents: number, participants: SplitParticipant[]): Map<string, number> {
  const totalFixed = participants.reduce((sum, p) => sum + (p.amountCents ?? 0), 0);
  if (totalFixed !== totalCents) {
    throw new ValidationError('Fixed amounts must sum to the total expense amount');
  }

  const result = new Map<string, number>();
  participants.forEach((p) => {
    result.set(p.userId, p.amountCents ?? 0);
  });
  return result;
}

export function formatCents(cents: number): string {
  const dollars = cents / 100;
  return dollars.toFixed(2);
}

import { PrismaClient, SplitType } from '@prisma/client';
import { ConflictError, NotFoundError, ValidationError } from '../utils/errors.js';
import { splitEqual, splitPercentage, splitFixed, type SplitParticipant } from '../utils/money.js';
import { assertMembership } from './groupService.js';
import type { CreateExpenseInput, UpdateExpenseInput } from '../types/schemas.js';

const prisma = new PrismaClient();

function calculateShares(
  splitType: SplitType,
  amountCents: number,
  participants: SplitParticipant[]
): Map<string, number> {
  switch (splitType) {
    case 'EQUAL':
      return splitEqual(amountCents, participants);
    case 'PERCENTAGE':
      return splitPercentage(amountCents, participants);
    case 'FIXED':
      return splitFixed(amountCents, participants);
  }
}

export async function createExpense(userId: string, groupId: string, input: CreateExpenseInput) {
  await assertMembership(userId, groupId);

  const shares = calculateShares(
    input.splitType as SplitType,
    input.amountCents,
    input.participants
  );

  const expense = await prisma.$transaction(async (tx) => {
    const exp = await tx.expense.create({
      data: {
        groupId,
        payerId: input.payerId,
        description: input.description,
        amountCents: input.amountCents,
        date: new Date(input.date),
        splitType: input.splitType as SplitType,
        shares: {
          create: input.participants.map((p) => ({
            userId: p.userId,
            amountCents: shares.get(p.userId) ?? 0,
            percentage: p.percentage ?? null,
          })),
        },
      },
      include: {
        shares: {
          include: { user: { select: { id: true, displayName: true } } },
        },
        payer: { select: { id: true, displayName: true } },
      },
    });

    // Create notifications for group members except the creator
    const members = await tx.groupMember.findMany({
      where: { groupId, userId: { not: userId } },
    });

    if (members.length > 0) {
      await tx.notification.createMany({
        data: members.map((m) => ({
          userId: m.userId,
          type: 'EXPENSE_CREATED' as const,
          data: {
            expenseId: exp.id,
            groupId,
            description: input.description,
            amountCents: input.amountCents,
            createdBy: userId,
          },
        })),
      });
    }

    return exp;
  });

  return expense;
}

export async function updateExpense(userId: string, groupId: string, expenseId: string, input: UpdateExpenseInput) {
  await assertMembership(userId, groupId);

  const existing = await prisma.expense.findUnique({
    where: { id: expenseId },
    include: { shares: true },
  });

  if (!existing || existing.groupId !== groupId) {
    throw new NotFoundError('Expense not found');
  }

  if (existing.version !== input.version) {
    throw new ConflictError('Expense was modified by another user. Please refresh and retry.');
  }

  const shares = calculateShares(
    input.splitType as SplitType,
    input.amountCents,
    input.participants
  );

  const expense = await prisma.$transaction(async (tx) => {
    // Delete old shares
    await tx.expenseShare.deleteMany({ where: { expenseId } });

    // Update expense
    const exp = await tx.expense.update({
      where: { id: expenseId },
      data: {
        payerId: input.payerId,
        description: input.description,
        amountCents: input.amountCents,
        date: new Date(input.date),
        splitType: input.splitType as SplitType,
        version: { increment: 1 },
        shares: {
          create: input.participants.map((p) => ({
            userId: p.userId,
            amountCents: shares.get(p.userId) ?? 0,
            percentage: p.percentage ?? null,
          })),
        },
      },
      include: {
        shares: {
          include: { user: { select: { id: true, displayName: true } } },
        },
        payer: { select: { id: true, displayName: true } },
      },
    });

    // Create audit log
    await tx.auditLog.create({
      data: {
        expenseId,
        userId,
        action: 'edit',
        data: {
          previous: {
            description: existing.description,
            amountCents: existing.amountCents,
            splitType: existing.splitType,
            shares: existing.shares,
          },
          current: {
            description: input.description,
            amountCents: input.amountCents,
            splitType: input.splitType,
          },
        },
      },
    });

    return exp;
  });

  return expense;
}

export async function deleteExpense(userId: string, groupId: string, expenseId: string) {
  await assertMembership(userId, groupId);

  const existing = await prisma.expense.findUnique({
    where: { id: expenseId },
    include: { shares: true },
  });

  if (!existing || existing.groupId !== groupId) {
    throw new NotFoundError('Expense not found');
  }

  await prisma.$transaction(async (tx) => {
    // Create audit log before deletion
    await tx.auditLog.create({
      data: {
        expenseId,
        userId,
        action: 'delete',
        data: {
          description: existing.description,
          amountCents: existing.amountCents,
          splitType: existing.splitType,
          shares: existing.shares,
        },
      },
    });

    await tx.expense.delete({ where: { id: expenseId } });
  });
}

export async function listExpenses(userId: string, groupId: string, page: number = 1) {
  await assertMembership(userId, groupId);

  const pageSize = 20;
  const [expenses, total] = await Promise.all([
    prisma.expense.findMany({
      where: { groupId },
      include: {
        payer: { select: { id: true, displayName: true } },
        shares: {
          include: { user: { select: { id: true, displayName: true } } },
        },
      },
      orderBy: { date: 'desc' },
      skip: (page - 1) * pageSize,
      take: pageSize,
    }),
    prisma.expense.count({ where: { groupId } }),
  ]);

  return {
    expenses,
    pagination: {
      page,
      pageSize,
      total,
      totalPages: Math.ceil(total / pageSize),
    },
  };
}

export async function getExpense(userId: string, groupId: string, expenseId: string) {
  await assertMembership(userId, groupId);

  const expense = await prisma.expense.findUnique({
    where: { id: expenseId },
    include: {
      payer: { select: { id: true, displayName: true } },
      shares: {
        include: { user: { select: { id: true, displayName: true } } },
      },
    },
  });

  if (!expense || expense.groupId !== groupId) {
    throw new NotFoundError('Expense not found');
  }

  return expense;
}

import { Router } from 'express';
import { requireAuth } from '../middleware/auth.js';
import { validate } from '../middleware/validate.js';
import { createExpenseSchema, updateExpenseSchema } from '../types/schemas.js';
import * as expenseService from '../services/expenseService.js';

const router = Router({ mergeParams: true });

router.post('/', requireAuth, validate(createExpenseSchema), async (req, res, next) => {
  try {
    const expense = await expenseService.createExpense(
      req.user!.userId,
      req.params.groupId as string,
      req.body
    );
    res.status(201).json({ data: expense });
  } catch (err) {
    next(err);
  }
});

router.get('/', requireAuth, async (req, res, next) => {
  try {
    const page = parseInt(req.query.page as string) || 1;
    const result = await expenseService.listExpenses(
      req.user!.userId,
      req.params.groupId as string,
      page
    );
    res.json({ data: result });
  } catch (err) {
    next(err);
  }
});

router.get('/:expenseId', requireAuth, async (req, res, next) => {
  try {
    const expense = await expenseService.getExpense(
      req.user!.userId,
      req.params.groupId as string,
      req.params.expenseId as string
    );
    res.json({ data: expense });
  } catch (err) {
    next(err);
  }
});

router.put('/:expenseId', requireAuth, validate(updateExpenseSchema), async (req, res, next) => {
  try {
    const expense = await expenseService.updateExpense(
      req.user!.userId,
      req.params.groupId as string,
      req.params.expenseId as string,
      req.body
    );
    res.json({ data: expense });
  } catch (err) {
    next(err);
  }
});

router.delete('/:expenseId', requireAuth, async (req, res, next) => {
  try {
    await expenseService.deleteExpense(
      req.user!.userId,
      req.params.groupId as string,
      req.params.expenseId as string
    );
    res.json({ data: { message: 'Expense deleted' } });
  } catch (err) {
    next(err);
  }
});

export default router;

