import { PrismaClient } from '@prisma/client';
import { assertMembership } from './groupService.js';

const prisma = new PrismaClient();

interface Balance {
  userId: string;
  displayName: string;
  balanceCents: number;
}

interface Debt {
  fromUserId: string;
  fromDisplayName: string;
  toUserId: string;
  toDisplayName: string;
  amountCents: number;
}

export async function getBalances(userId: string, groupId: string): Promise<Balance[]> {
  await assertMembership(userId, groupId);

  const members = await prisma.groupMember.findMany({
    where: { groupId },
    include: { user: { select: { id: true, displayName: true } } },
  });

  const expenses = await prisma.expense.findMany({
    where: { groupId },
    include: { shares: true },
  });

  const settlements = await prisma.settlement.findMany({
    where: { groupId },
  });

  // Calculate net balances: positive = owed money, negative = owes money
  const balanceMap = new Map<string, number>();
  members.forEach((m) => balanceMap.set(m.userId, 0));

  for (const expense of expenses) {
    // Payer is owed the full amount
    balanceMap.set(expense.payerId, (balanceMap.get(expense.payerId) ?? 0) + expense.amountCents);
    // Each participant owes their share
    for (const share of expense.shares) {
      balanceMap.set(share.userId, (balanceMap.get(share.userId) ?? 0) - share.amountCents);
    }
  }

  // Settlements: payer reduces their debt, recipient reduces what they're owed
  for (const settlement of settlements) {
    balanceMap.set(settlement.payerId, (balanceMap.get(settlement.payerId) ?? 0) + settlement.amountCents);
    balanceMap.set(settlement.recipientId, (balanceMap.get(settlement.recipientId) ?? 0) - settlement.amountCents);
  }

  const memberMap = new Map(members.map((m) => [m.userId, m.user.displayName]));

  return members.map((m) => ({
    userId: m.userId,
    displayName: memberMap.get(m.userId) ?? 'Unknown',
    balanceCents: balanceMap.get(m.userId) ?? 0,
  }));
}

export async function getDebts(userId: string, groupId: string): Promise<Debt[]> {
  const balances = await getBalances(userId, groupId);

  // Separate debtors (negative balance) and creditors (positive balance)
  const debtors = balances.filter((b) => b.balanceCents < 0).map((b) => ({ ...b }));
  const creditors = balances.filter((b) => b.balanceCents > 0).map((b) => ({ ...b }));

  return minimizeSettlements(debtors, creditors);
}

function minimizeSettlements(
  debtors: { userId: string; displayName: string; balanceCents: number }[],
  creditors: { userId: string; displayName: string; balanceCents: number }[]
): Debt[] {
  // Sort debtors by debt ascending (most negative first), creditors by credit descending
  debtors.sort((a, b) => a.balanceCents - b.balanceCents);
  creditors.sort((a, b) => b.balanceCents - a.balanceCents);

  const debts: Debt[] = [];
  let i = 0;
  let j = 0;

  while (i < debtors.length && j < creditors.length) {
    const debtAmount = Math.abs(debtors[i].balanceCents);
    const creditAmount = creditors[j].balanceCents;
    const settleAmount = Math.min(debtAmount, creditAmount);

    if (settleAmount > 0) {
      debts.push({
        fromUserId: debtors[i].userId,
        fromDisplayName: debtors[i].displayName,
        toUserId: creditors[j].userId,
        toDisplayName: creditors[j].displayName,
        amountCents: settleAmount,
      });
    }

    debtors[i].balanceCents += settleAmount;
    creditors[j].balanceCents -= settleAmount;

    if (debtors[i].balanceCents === 0) i++;
    if (creditors[j].balanceCents === 0) j++;
  }

  return debts;
}

export async function getSettlementSuggestions(userId: string, groupId: string) {
  const debts = await getDebts(userId, groupId);

  // Fetch PayPal links for recipients
  const recipientIds = [...new Set(debts.map((d) => d.toUserId))];
  const users = await prisma.user.findMany({
    where: { id: { in: recipientIds } },
    select: { id: true, paypalLink: true },
  });
  const paypalMap = new Map(users.map((u) => [u.id, u.paypalLink]));

  return debts.map((d) => ({
    ...d,
    recipientPaypalLink: paypalMap.get(d.toUserId) ?? null,
  }));
}

import { PrismaClient } from '@prisma/client';
import { NotFoundError, ValidationError } from '../utils/errors.js';
import { assertMembership } from './groupService.js';
import type { CreateSettlementInput } from '../types/schemas.js';

const prisma = new PrismaClient();

export async function createSettlement(userId: string, groupId: string, input: CreateSettlementInput) {
  await assertMembership(userId, groupId);

  // Verify both payer and recipient are group members
  const members = await prisma.groupMember.findMany({
    where: { groupId, userId: { in: [input.payerId, input.recipientId] } },
  });
  if (members.length !== 2) {
    throw new ValidationError('Both payer and recipient must be group members');
  }

  if (input.payerId === input.recipientId) {
    throw new ValidationError('Payer and recipient must be different');
  }

  const settlement = await prisma.$transaction(async (tx) => {
    const s = await tx.settlement.create({
      data: {
        groupId,
        payerId: input.payerId,
        recipientId: input.recipientId,
        amountCents: input.amountCents,
      },
      include: {
        payer: { select: { id: true, displayName: true } },
        recipient: { select: { id: true, displayName: true } },
      },
    });

    // Notify both parties (if they're not the one recording)
    const notifyUserIds = [input.payerId, input.recipientId].filter((id) => id !== userId);
    if (notifyUserIds.length > 0) {
      await tx.notification.createMany({
        data: notifyUserIds.map((uid) => ({
          userId: uid,
          type: 'SETTLEMENT_RECORDED' as const,
          data: {
            settlementId: s.id,
            groupId,
            amountCents: input.amountCents,
            payerId: input.payerId,
            recipientId: input.recipientId,
          },
        })),
      });
    }

    return s;
  });

  return settlement;
}

export async function listSettlements(userId: string, groupId: string) {
  await assertMembership(userId, groupId);

  const settlements = await prisma.settlement.findMany({
    where: { groupId },
    include: {
      payer: { select: { id: true, displayName: true } },
      recipient: { select: { id: true, displayName: true } },
    },
    orderBy: { createdAt: 'desc' },
  });

  return settlements;
}

