        ) : suggestions.length === 0 ? (
          <p className="text-gray-600">No settlements needed — all balanced!</p>
        ) : (
          <ul className="divide-y divide-gray-100">
            {suggestions.map((s, i) => (
              <li key={i} className="py-3">
                <div className="flex justify-between items-center">
                  <span>
                    <span className="font-medium">{s.fromDisplayName}</span>
                    {' pays '}
                    <span className="font-medium">{s.toDisplayName}</span>
                  </span>
                  <span className="font-semibold">${formatCents(s.amountCents)}</span>
