                  <a href={s.recipientPaypalLink} target="_blank" rel="noopener noreferrer" className="text-sm text-blue-600 hover:text-blue-500">
                    Pay via PayPal
                  </a>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>
