import { useState, useEffect, type FormEvent } from 'react';
import { useParams, Link } from 'react-router-dom';
import { apiFetch, ApiError } from '../../utils/api';

interface Member {
  id: string;
  user: { id: string; displayName: string };
}

interface Settlement {
  id: string;
  amountCents: number;
  createdAt: string;
  payer: { id: string; displayName: string };
  recipient: { id: string; displayName: string };
}

function formatCents(cents: number): string {
  return (cents / 100).toFixed(2);
}

export default function SettlementsPage() {
  const { groupId } = useParams<{ groupId: string }>();
  const [settlements, setSettlements] = useState<Settlement[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [payerId, setPayerId] = useState('');
  const [recipientId, setRecipientId] = useState('');
  const [amount, setAmount] = useState('');
  const [error, setError] = useState('');
  const [creating, setCreating] = useState(false);

  const loadData = async () => {
    try {
      const [s, m] = await Promise.all([
        apiFetch<Settlement[]>(`/groups/${groupId}/settlements`),
        apiFetch<Member[]>(`/groups/${groupId}/members`),
      ]);
      setSettlements(s);
      setMembers(m);
    } catch {
      // handle silently
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [groupId]);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setCreating(true);
    const amountCents = Math.round(parseFloat(amount) * 100);
    if (isNaN(amountCents) || amountCents <= 0) {
      setError('Please enter a valid positive amount');
      setCreating(false);
      return;
    }
    try {
      await apiFetch(`/groups/${groupId}/settlements`, {
        method: 'POST',
        body: JSON.stringify({ payerId, recipientId, amountCents }),
      });
      setShowForm(false);
      setAmount('');
      await loadData();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to record settlement');
    } finally {
      setCreating(false);
    }
  };

  if (loading) return <div className="max-w-4xl mx-auto p-6">Loading...</div>;

  return (
    <div className="max-w-4xl mx-auto p-6">
      <Link to={`/groups/${groupId}`} className="text-blue-600 hover:text-blue-500 text-sm mb-4 inline-block">&larr; Back to Group</Link>

      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-900">Settlements</h1>
        <button onClick={() => setShowForm(!showForm)} className="py-2 px-4 rounded-md text-sm font-medium text-white bg-blue-600 hover:bg-blue-700">
          Record Settlement
        </button>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded mb-4" role="alert">{error}</div>
      )}

      {showForm && (
        <form onSubmit={handleSubmit} className="bg-white p-6 rounded-lg shadow mb-6 space-y-4">
          <div>
            <label htmlFor="payer" className="block text-sm font-medium text-gray-700">Payer</label>
            <select id="payer" value={payerId} onChange={(e) => setPayerId(e.target.value)} required
              className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2">
              <option value="">Select payer</option>
              {members.map((m) => (
                <option key={m.user.id} value={m.user.id}>{m.user.displayName}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="recipient" className="block text-sm font-medium text-gray-700">Recipient</label>
            <select id="recipient" value={recipientId} onChange={(e) => setRecipientId(e.target.value)} required
              className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2">
              <option value="">Select recipient</option>
              {members.map((m) => (
                <option key={m.user.id} value={m.user.id}>{m.user.displayName}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="settlementAmount" className="block text-sm font-medium text-gray-700">Amount ($)</label>
            <input id="settlementAmount" type="number" step="0.01" min="0.01" value={amount}
              onChange={(e) => setAmount(e.target.value)} required
              className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2" />
          </div>
          <button type="submit" disabled={creating}
            className="py-2 px-4 rounded-md text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 disabled:opacity-50">
            {creating ? 'Recording...' : 'Record'}
          </button>
        </form>
      )}

      {settlements.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-lg shadow">
          <p className="text-gray-600">No settlements recorded yet.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {settlements.map((s) => (
            <div key={s.id} className="bg-white p-4 rounded-lg shadow">
              <div className="flex justify-between items-center">
                <div>
                  <span className="font-medium">{s.payer.displayName}</span>
                  {' paid '}
                  <span className="font-medium">{s.recipient.displayName}</span>
                </div>
                <div className="text-right">
                  <span className="font-semibold">${formatCents(s.amountCents)}</span>
                  <p className="text-xs text-gray-500">{new Date(s.createdAt).toLocaleDateString()}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { apiFetch } from '../../utils/api';

interface Notification {
  id: string;
  type: string;
  data: Record<string, unknown>;
  read: boolean;
  createdAt: string;
}

function notificationMessage(n: Notification): string {
  switch (n.type) {
    case 'GROUP_INVITATION':
      return `You were invited to ${(n.data as { groupName?: string }).groupName ?? 'a group'} by ${(n.data as { invitedBy?: string }).invitedBy ?? 'someone'}`;
    case 'EXPENSE_CREATED':
      return `New expense "${(n.data as { description?: string }).description ?? ''}" ($${((n.data as { amountCents?: number }).amountCents ?? 0) / 100}) added`;
    case 'SETTLEMENT_RECORDED':
      return `A settlement of $${((n.data as { amountCents?: number }).amountCents ?? 0) / 100} was recorded`;
    default:
      return 'New notification';
  }
}

export default function NotificationsPage() {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [loading, setLoading] = useState(true);

  const loadNotifications = async () => {
    try {
      const data = await apiFetch<Notification[]>('/notifications');
      setNotifications(data);
    } catch {
      // handle silently
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadNotifications();
  }, []);

  const markAsRead = async (id: string) => {
    try {
      await apiFetch(`/notifications/${id}/read`, { method: 'POST' });
      setNotifications((prev) =>
        prev.map((n) => (n.id === id ? { ...n, read: true } : n))
      );
    } catch {
      // handle silently
    }
  };

  const markAllRead = async () => {
    try {
      await apiFetch('/notifications/read-all', { method: 'POST' });
      setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
    } catch {
      // handle silently
    }
  };

  if (loading) return <div className="max-w-4xl mx-auto p-6">Loading...</div>;

  const unreadCount = notifications.filter((n) => !n.read).length;

  return (
    <div className="max-w-4xl mx-auto p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-900">
          Notifications
          {unreadCount > 0 && (
            <span className="ml-2 text-sm bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full">{unreadCount} unread</span>
          )}
        </h1>
        {unreadCount > 0 && (
          <button onClick={markAllRead} className="text-sm text-blue-600 hover:text-blue-500">
            Mark all as read
          </button>
        )}
      </div>

      {notifications.length === 0 ? (
        <p className="text-gray-600">No notifications.</p>
      ) : (
        <div className="space-y-2">
          {notifications.map((n) => (
            <div
              key={n.id}
              className={`p-4 rounded-lg shadow cursor-pointer ${n.read ? 'bg-white' : 'bg-blue-50 border border-blue-200'}`}
              onClick={() => !n.read && markAsRead(n.id)}
            >
              <p className="text-sm text-gray-900">{notificationMessage(n)}</p>
              <p className="text-xs text-gray-500 mt-1">{new Date(n.createdAt).toLocaleString()}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

