import { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { apiFetch } from '../../utils/api';

interface ExpenseShare {
  userId: string;
  amountCents: number;
  user: { id: string; displayName: string };
}

interface Expense {
  id: string;
  description: string;
  amountCents: number;
  date: string;
  splitType: string;
  version: number;
  payer: { id: string; displayName: string };
  shares: ExpenseShare[];
}

interface ExpenseListResponse {
  expenses: Expense[];
  pagination: { page: number; pageSize: number; total: number; totalPages: number };
}

function formatCents(cents: number): string {
  return (cents / 100).toFixed(2);
}

export default function ExpenseListPage() {
  const { groupId } = useParams<{ groupId: string }>();
  const [data, setData] = useState<ExpenseListResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);

  const loadExpenses = async (p: number) => {
    setLoading(true);
    try {
      const result = await apiFetch<ExpenseListResponse>(`/groups/${groupId}/expenses?page=${p}`);
      setData(result);
    } catch {
      // handle error silently
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadExpenses(page);
  }, [groupId, page]);

  return (
    <div className="max-w-4xl mx-auto p-6">
      <Link to={`/groups/${groupId}`} className="text-blue-600 hover:text-blue-500 text-sm mb-4 inline-block">&larr; Back to Group</Link>

      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-900">Expenses</h1>
        <Link
          to={`/groups/${groupId}/expenses/new`}
          className="py-2 px-4 rounded-md text-sm font-medium text-white bg-blue-600 hover:bg-blue-700"
        >
          Add Expense
        </Link>
      </div>

      {loading ? (
        <p>Loading...</p>
      ) : !data || data.expenses.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-lg shadow">
          <p className="text-gray-600">No expenses yet. Add the first expense to get started.</p>
        </div>
      ) : (
        <>
          <div className="space-y-3">
            {data.expenses.map((exp) => (
              <Link
                key={exp.id}
                to={`/groups/${groupId}/expenses/${exp.id}`}
                className="block bg-white p-4 rounded-lg shadow hover:shadow-md transition-shadow"
              >
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="font-semibold text-gray-900">{exp.description}</h3>
                    <p className="text-sm text-gray-500">
                      Paid by {exp.payer.displayName} &middot; {new Date(exp.date).toLocaleDateString()} &middot; {exp.splitType.toLowerCase()} split
                    </p>
                  </div>
                  <span className="font-semibold text-gray-900">${formatCents(exp.amountCents)}</span>
                </div>
              </Link>
            ))}
