            <div className="flex justify-center gap-2 mt-6">
              <button
                onClick={() => setPage(page - 1)}
                disabled={page <= 1}
                className="px-3 py-1 rounded border text-sm disabled:opacity-50"
              >
                Previous
              </button>
              <span className="px-3 py-1 text-sm text-gray-600">
                Page {page} of {data.pagination.totalPages}
              </span>
              <button
                onClick={() => setPage(page + 1)}
                disabled={page >= data.pagination.totalPages}
                className="px-3 py-1 rounded border text-sm disabled:opacity-50"
              >
                Next
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

import { useState, useEffect, type FormEvent } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { apiFetch, ApiError } from '../../utils/api';
import { useAuth } from '../auth/AuthContext';

interface Member {
  id: string;
  user: { id: string; displayName: string };
}

export default function CreateExpensePage() {
  const { groupId } = useParams<{ groupId: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [members, setMembers] = useState<Member[]>([]);
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [payerId, setPayerId] = useState(user?.id || '');
  const [splitType, setSplitType] = useState<'EQUAL' | 'PERCENTAGE' | 'FIXED'>('EQUAL');
  const [selectedParticipants, setSelectedParticipants] = useState<Set<string>>(new Set());
  const [percentages, setPercentages] = useState<Record<string, string>>({});
  const [fixedAmounts, setFixedAmounts] = useState<Record<string, string>>({});
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const data = await apiFetch<Member[]>(`/groups/${groupId}/members`);
        setMembers(data);
        // Select all members by default
        setSelectedParticipants(new Set(data.map((m) => m.user.id)));
      } catch {
        setError('Failed to load members');
      }
    })();
  }, [groupId]);

  const toggleParticipant = (userId: string) => {
    setSelectedParticipants((prev) => {
      const next = new Set(prev);
      if (next.has(userId)) next.delete(userId);
      else next.add(userId);
      return next;
    });
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    const amountCents = Math.round(parseFloat(amount) * 100);
    if (isNaN(amountCents) || amountCents <= 0) {
      setError('Please enter a valid positive amount');
      setLoading(false);
      return;
    }

    if (selectedParticipants.size === 0) {
      setError('At least one participant is required');
      setLoading(false);
      return;
    }

    const participants = Array.from(selectedParticipants).map((userId) => {
      const p: { userId: string; percentage?: number; amountCents?: number } = { userId };
      if (splitType === 'PERCENTAGE') {
        p.percentage = parseFloat(percentages[userId] || '0');
      } else if (splitType === 'FIXED') {
        p.amountCents = Math.round(parseFloat(fixedAmounts[userId] || '0') * 100);
      }
      return p;
    });

    try {
      await apiFetch(`/groups/${groupId}/expenses`, {
        method: 'POST',
        body: JSON.stringify({
          description,
          amountCents,
          date,
          payerId,
          splitType,
          participants,
        }),
      });
      navigate(`/groups/${groupId}/expenses`);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to create expense');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6">
      <Link to={`/groups/${groupId}/expenses`} className="text-blue-600 hover:text-blue-500 text-sm mb-4 inline-block">&larr; Back to Expenses</Link>
      <h1 className="text-2xl font-bold text-gray-900 mb-6">Add Expense</h1>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded mb-4" role="alert">{error}</div>
      )}

      <form onSubmit={handleSubmit} className="space-y-4 bg-white p-6 rounded-lg shadow">
        <div>
          <label htmlFor="description" className="block text-sm font-medium text-gray-700">Description</label>
          <input id="description" type="text" value={description} onChange={(e) => setDescription(e.target.value)} required
            className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500" />
        </div>

        <div>
          <label htmlFor="amount" className="block text-sm font-medium text-gray-700">Amount ($)</label>
          <input id="amount" type="number" step="0.01" min="0.01" value={amount} onChange={(e) => setAmount(e.target.value)} required
            className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500" />
        </div>

        <div>
          <label htmlFor="date" className="block text-sm font-medium text-gray-700">Date</label>
          <input id="date" type="date" value={date} onChange={(e) => setDate(e.target.value)} required
            className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500" />
        </div>

        <div>
          <label htmlFor="payer" className="block text-sm font-medium text-gray-700">Paid by</label>
          <select id="payer" value={payerId} onChange={(e) => setPayerId(e.target.value)}
            className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500">
            {members.map((m) => (
              <option key={m.user.id} value={m.user.id}>{m.user.displayName}</option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">Split Type</label>
          <div className="flex gap-4">
            {(['EQUAL', 'PERCENTAGE', 'FIXED'] as const).map((st) => (
              <label key={st} className="flex items-center gap-1">
                <input type="radio" name="splitType" value={st} checked={splitType === st} onChange={() => setSplitType(st)} />
                <span className="text-sm">{st.charAt(0) + st.slice(1).toLowerCase()}</span>
              </label>
            ))}
          </div>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">Participants</label>
          <div className="space-y-2">
            {members.map((m) => (
              <div key={m.user.id} className="flex items-center gap-3">
                <label className="flex items-center gap-2 flex-1">
                  <input type="checkbox" checked={selectedParticipants.has(m.user.id)} onChange={() => toggleParticipant(m.user.id)} />
                  <span className="text-sm">{m.user.displayName}</span>
                </label>
                {splitType === 'PERCENTAGE' && selectedParticipants.has(m.user.id) && (
                  <input type="number" step="0.01" placeholder="%" value={percentages[m.user.id] || ''}
                    onChange={(e) => setPercentages({ ...percentages, [m.user.id]: e.target.value })}
                    className="w-20 rounded-md border border-gray-300 px-2 py-1 text-sm" />
                )}
                {splitType === 'FIXED' && selectedParticipants.has(m.user.id) && (
                  <input type="number" step="0.01" placeholder="$" value={fixedAmounts[m.user.id] || ''}
                    onChange={(e) => setFixedAmounts({ ...fixedAmounts, [m.user.id]: e.target.value })}
                    className="w-24 rounded-md border border-gray-300 px-2 py-1 text-sm" />
                )}
              </div>
            ))}
          </div>
        </div>

        <button type="submit" disabled={loading}
          className="py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50">
          {loading ? 'Creating...' : 'Create Expense'}
        </button>
      </form>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { apiFetch, ApiError } from '../../utils/api';

interface Expense {
  id: string;
  description: string;
  amountCents: number;
  date: string;
  splitType: string;
  version: number;
  payer: { id: string; displayName: string };
  shares: { userId: string; amountCents: number; user: { id: string; displayName: string } }[];
}

function formatCents(cents: number): string {
  return (cents / 100).toFixed(2);
}

export default function ExpenseDetailPage() {
  const { groupId, expenseId } = useParams<{ groupId: string; expenseId: string }>();
  const navigate = useNavigate();
  const [expense, setExpense] = useState<Expense | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const data = await apiFetch<Expense>(`/groups/${groupId}/expenses/${expenseId}`);
        setExpense(data);
      } catch {
        setError('Failed to load expense');
      } finally {
        setLoading(false);
      }
    })();
  }, [groupId, expenseId]);

  const handleDelete = async () => {
    try {
      await apiFetch(`/groups/${groupId}/expenses/${expenseId}`, { method: 'DELETE' });
      navigate(`/groups/${groupId}/expenses`);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to delete expense');
    }
  };

  if (loading) return <div className="max-w-2xl mx-auto p-6">Loading...</div>;
  if (!expense) return <div className="max-w-2xl mx-auto p-6">Expense not found</div>;

  return (
    <div className="max-w-2xl mx-auto p-6">
      <Link to={`/groups/${groupId}/expenses`} className="text-blue-600 hover:text-blue-500 text-sm mb-4 inline-block">&larr; Back to Expenses</Link>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded mb-4" role="alert">{error}</div>
      )}

      <div className="bg-white p-6 rounded-lg shadow">
        <div className="flex justify-between items-start mb-4">
          <h1 className="text-2xl font-bold text-gray-900">{expense.description}</h1>
          <span className="text-2xl font-bold text-gray-900">${formatCents(expense.amountCents)}</span>
        </div>

        <div className="space-y-2 text-sm text-gray-600 mb-6">
          <p>Paid by: {expense.payer.displayName}</p>
          <p>Date: {new Date(expense.date).toLocaleDateString()}</p>
          <p>Split type: {expense.splitType.toLowerCase()}</p>
        </div>

        <h2 className="text-lg font-semibold text-gray-900 mb-3">Shares</h2>
        <ul className="divide-y divide-gray-100 mb-6">
          {expense.shares.map((share) => (
            <li key={share.userId} className="py-2 flex justify-between">
              <span>{share.user.displayName}</span>
              <span className="font-medium">${formatCents(share.amountCents)}</span>
            </li>
          ))}
        </ul>

        <div className="flex gap-3">
          {showDeleteConfirm ? (
            <>
              <button onClick={handleDelete} className="py-2 px-4 rounded-md text-sm font-medium text-white bg-red-600 hover:bg-red-700">
                Confirm Delete
              </button>
              <button onClick={() => setShowDeleteConfirm(false)} className="py-2 px-4 rounded-md text-sm font-medium text-gray-700 bg-gray-100 hover:bg-gray-200">
                Cancel
              </button>
            </>
          ) : (
            <button onClick={() => setShowDeleteConfirm(true)} className="py-2 px-4 rounded-md text-sm font-medium text-red-600 border border-red-300 hover:bg-red-50">
              Delete Expense
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { apiFetch } from '../../utils/api';

interface Balance {
  userId: string;
  displayName: string;
  balanceCents: number;
}

interface Suggestion {
  fromUserId: string;
  fromDisplayName: string;
  toUserId: string;
  toDisplayName: string;
  amountCents: number;
  recipientPaypalLink: string | null;
}

function formatCents(cents: number): string {
  return (cents / 100).toFixed(2);
}

export default function BalancesPage() {
  const { groupId } = useParams<{ groupId: string }>();
  const [balances, setBalances] = useState<Balance[]>([]);
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      try {
        const [b, s] = await Promise.all([
          apiFetch<Balance[]>(`/groups/${groupId}/balances`),
          apiFetch<Suggestion[]>(`/groups/${groupId}/balances/suggestions`),
        ]);
        setBalances(b);
        setSuggestions(s);
      } catch {
        // handle silently
      } finally {
        setLoading(false);
      }
    })();
  }, [groupId]);

  if (loading) return <div className="max-w-4xl mx-auto p-6">Loading...</div>;

  const allSettled = balances.every((b) => b.balanceCents === 0);

  return (
    <div className="max-w-4xl mx-auto p-6">
      <Link to={`/groups/${groupId}`} className="text-blue-600 hover:text-blue-500 text-sm mb-4 inline-block">&larr; Back to Group</Link>
      <h1 className="text-2xl font-bold text-gray-900 mb-6">Balances</h1>

      <div className="bg-white p-6 rounded-lg shadow mb-6">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Per-Member Balances</h2>
        {balances.length === 0 ? (
          <p className="text-gray-600">No members found.</p>
        ) : (
          <ul className="divide-y divide-gray-100">
            {balances.map((b) => (
              <li key={b.userId} className="py-3 flex justify-between items-center">
                <span className="text-gray-900">{b.displayName}</span>
                <span className={`font-semibold ${b.balanceCents > 0 ? 'text-green-600' : b.balanceCents < 0 ? 'text-red-600' : 'text-gray-500'}`}>
                  {b.balanceCents > 0 ? '+' : ''}${formatCents(b.balanceCents)}
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>

      <div className="bg-white p-6 rounded-lg shadow">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Settlement Suggestions</h2>
        {allSettled ? (
          <p className="text-green-600 font-medium">All settled up!</p>
        ) : suggestions.length === 0 ? (
          <p className="text-gray-600">No settlements needed — all balanced!</p>
        ) : (
          <ul className="divide-y divide-gray-100">
            {suggestions.map((s, i) => (
              <li key={i} className="py-3">
                <div className="flex justify-between items-center">
                  <span>
                    <span className="font-medium">{s.fromDisplayName}</span>
                    {' pays '}
                    <span className="font-medium">{s.toDisplayName}</span>
                  </span>
                  <span className="font-semibold">${formatCents(s.amountCents)}</span>
                </div>
                {s.recipientPaypalLink && (
                  <a href={s.recipientPaypalLink} target="_blank" rel="noopener noreferrer" className="text-sm text-blue-600 hover:text-blue-500">
                    Pay via PayPal
                  </a>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, type FormEvent } from 'react';
import { useParams, Link } from 'react-router-dom';
import { apiFetch, ApiError } from '../../utils/api';

interface Member {
  id: string;
  user: { id: string; displayName: string };
}

interface Settlement {
  id: string;
  amountCents: number;
  createdAt: string;
  payer: { id: string; displayName: string };
  recipient: { id: string; displayName: string };
}

function formatCents(cents: number): string {
  return (cents / 100).toFixed(2);
}

export default function SettlementsPage() {
  const { groupId } = useParams<{ groupId: string }>();
  const [settlements, setSettlements] = useState<Settlement[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [payerId, setPayerId] = useState('');
  const [recipientId, setRecipientId] = useState('');
  const [amount, setAmount] = useState('');
  const [error, setError] = useState('');
  const [creating, setCreating] = useState(false);

  const loadData = async () => {
    try {
      const [s, m] = await Promise.all([
        apiFetch<Settlement[]>(`/groups/${groupId}/settlements`),
        apiFetch<Member[]>(`/groups/${groupId}/members`),
      ]);
      setSettlements(s);
      setMembers(m);
    } catch {
      // handle silently
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [groupId]);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setCreating(true);
    const amountCents = Math.round(parseFloat(amount) * 100);
    if (isNaN(amountCents) || amountCents <= 0) {
      setError('Please enter a valid positive amount');
      setCreating(false);
      return;
    }
    try {
      await apiFetch(`/groups/${groupId}/settlements`, {
        method: 'POST',
        body: JSON.stringify({ payerId, recipientId, amountCents }),
      });
      setShowForm(false);
      setAmount('');
      await loadData();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to record settlement');
    } finally {
      setCreating(false);
    }
  };

  if (loading) return <div className="max-w-4xl mx-auto p-6">Loading...</div>;

  return (
    <div className="max-w-4xl mx-auto p-6">
      <Link to={`/groups/${groupId}`} className="text-blue-600 hover:text-blue-500 text-sm mb-4 inline-block">&larr; Back to Group</Link>

      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-900">Settlements</h1>
        <button onClick={() => setShowForm(!showForm)} className="py-2 px-4 rounded-md text-sm font-medium text-white bg-blue-600 hover:bg-blue-700">
          Record Settlement
        </button>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded mb-4" role="alert">{error}</div>
      )}

      {showForm && (
        <form onSubmit={handleSubmit} className="bg-white p-6 rounded-lg shadow mb-6 space-y-4">
          <div>
            <label htmlFor="payer" className="block text-sm font-medium text-gray-700">Payer</label>
            <select id="payer" value={payerId} onChange={(e) => setPayerId(e.target.value)} required
              className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2">
              <option value="">Select payer</option>
              {members.map((m) => (
                <option key={m.user.id} value={m.user.id}>{m.user.displayName}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="recipient" className="block text-sm font-medium text-gray-700">Recipient</label>
            <select id="recipient" value={recipientId} onChange={(e) => setRecipientId(e.target.value)} required
              className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2">
              <option value="">Select recipient</option>
              {members.map((m) => (
                <option key={m.user.id} value={m.user.id}>{m.user.displayName}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="settlementAmount" className="block text-sm font-medium text-gray-700">Amount ($)</label>
            <input id="settlementAmount" type="number" step="0.01" min="0.01" value={amount}
              onChange={(e) => setAmount(e.target.value)} required
              className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2" />
          </div>
          <button type="submit" disabled={creating}
            className="py-2 px-4 rounded-md text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 disabled:opacity-50">
            {creating ? 'Recording...' : 'Record'}
          </button>
        </form>
      )}

      {settlements.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-lg shadow">
          <p className="text-gray-600">No settlements recorded yet.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {settlements.map((s) => (
            <div key={s.id} className="bg-white p-4 rounded-lg shadow">
              <div className="flex justify-between items-center">
                <div>
                  <span className="font-medium">{s.payer.displayName}</span>
                  {' paid '}
                  <span className="font-medium">{s.recipient.displayName}</span>
                </div>
                <div className="text-right">
                  <span className="font-semibold">${formatCents(s.amountCents)}</span>
                  <p className="text-xs text-gray-500">{new Date(s.createdAt).toLocaleDateString()}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { apiFetch } from '../../utils/api';

interface Notification {
  id: string;
  type: string;
  data: Record<string, unknown>;
  read: boolean;
  createdAt: string;
}

function notificationMessage(n: Notification): string {
  switch (n.type) {
    case 'GROUP_INVITATION':
      return `You were invited to ${(n.data as { groupName?: string }).groupName ?? 'a group'} by ${(n.data as { invitedBy?: string }).invitedBy ?? 'someone'}`;
    case 'EXPENSE_CREATED':
      return `New expense "${(n.data as { description?: string }).description ?? ''}" ($${((n.data as { amountCents?: number }).amountCents ?? 0) / 100}) added`;
    case 'SETTLEMENT_RECORDED':
      return `A settlement of $${((n.data as { amountCents?: number }).amountCents ?? 0) / 100} was recorded`;
    default:
      return 'New notification';
  }
}

export default function NotificationsPage() {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [loading, setLoading] = useState(true);

  const loadNotifications = async () => {
    try {
      const data = await apiFetch<Notification[]>('/notifications');
      setNotifications(data);
    } catch {
      // handle silently
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadNotifications();
  }, []);

  const markAsRead = async (id: string) => {
    try {
      await apiFetch(`/notifications/${id}/read`, { method: 'POST' });
      setNotifications((prev) =>
        prev.map((n) => (n.id === id ? { ...n, read: true } : n))
      );
    } catch {
      // handle silently
    }
  };

  const markAllRead = async () => {
    try {
      await apiFetch('/notifications/read-all', { method: 'POST' });
      setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
    } catch {
      // handle silently
    }
  };

  if (loading) return <div className="max-w-4xl mx-auto p-6">Loading...</div>;

  const unreadCount = notifications.filter((n) => !n.read).length;

  return (
    <div className="max-w-4xl mx-auto p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-900">
          Notifications
          {unreadCount > 0 && (
            <span className="ml-2 text-sm bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full">{unreadCount} unread</span>
          )}
        </h1>
        {unreadCount > 0 && (
          <button onClick={markAllRead} className="text-sm text-blue-600 hover:text-blue-500">
            Mark all as read
          </button>
        )}
      </div>

      {notifications.length === 0 ? (
        <p className="text-gray-600">No notifications.</p>
      ) : (
        <div className="space-y-2">
          {notifications.map((n) => (
            <div
              key={n.id}
              className={`p-4 rounded-lg shadow cursor-pointer ${n.read ? 'bg-white' : 'bg-blue-50 border border-blue-200'}`}
              onClick={() => !n.read && markAsRead(n.id)}
            >
              <p className="text-sm text-gray-900">{notificationMessage(n)}</p>
              <p className="text-xs text-gray-500 mt-1">{new Date(n.createdAt).toLocaleString()}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

