import type { Request, Response, NextFunction } from 'express';
import { verifyAccessToken, verifyRefreshToken, type TokenPayload } from '../services/authService.js';
import { UnauthorizedError } from '../utils/errors.js';
import jwt from 'jsonwebtoken';
import { config } from '../config/index.js';

declare global {
  namespace Express {
    interface Request {
      user?: TokenPayload;
    }
  }
}

export function requireAuth(req: Request, _res: Response, next: NextFunction): void {
  const accessToken = req.cookies?.accessToken;

  if (!accessToken) {
    next(new UnauthorizedError('Authentication required'));
    return;
  }

  try {
    const payload = verifyAccessToken(accessToken);
    req.user = payload;
    next();
  } catch {
    next(new UnauthorizedError('Invalid or expired token'));
  }
}

export function setTokenCookies(
  res: Response,
  accessToken: string,
  refreshToken: string
): void {
  res.cookie('accessToken', accessToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 15 * 60 * 1000, // 15 minutes
  });

  res.cookie('refreshToken', refreshToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
  });
}

export function clearTokenCookies(res: Response): void {
  res.clearCookie('accessToken');
  res.clearCookie('refreshToken');
}

import { PrismaClient, SplitType } from '@prisma/client';
import { ConflictError, NotFoundError, ValidationError } from '../utils/errors.js';
import { splitEqual, splitPercentage, splitFixed, type SplitParticipant } from '../utils/money.js';
import { assertMembership } from './groupService.js';
import type { CreateExpenseInput, UpdateExpenseInput } from '../types/schemas.js';

const prisma = new PrismaClient();

function calculateShares(
  splitType: SplitType,
  amountCents: number,
  participants: SplitParticipant[]
): Map<string, number> {
  switch (splitType) {
    case 'EQUAL':
      return splitEqual(amountCents, participants);
    case 'PERCENTAGE':
      return splitPercentage(amountCents, participants);
    case 'FIXED':
      return splitFixed(amountCents, participants);
  }
}

export async function createExpense(userId: string, groupId: string, input: CreateExpenseInput) {
  await assertMembership(userId, groupId);

  const shares = calculateShares(
    input.splitType as SplitType,
    input.amountCents,
    input.participants
  );

  const expense = await prisma.$transaction(async (tx) => {
    const exp = await tx.expense.create({
      data: {
        groupId,
        payerId: input.payerId,
        description: input.description,
        amountCents: input.amountCents,
        date: new Date(input.date),
        splitType: input.splitType as SplitType,
        shares: {
          create: input.participants.map((p) => ({
            userId: p.userId,
            amountCents: shares.get(p.userId) ?? 0,
            percentage: p.percentage ?? null,
          })),
        },
      },
      include: {
        shares: {
          include: { user: { select: { id: true, displayName: true } } },
        },
        payer: { select: { id: true, displayName: true } },
      },
    });

    // Create notifications for group members except the creator
    const members = await tx.groupMember.findMany({
      where: { groupId, userId: { not: userId } },
    });

    if (members.length > 0) {
      await tx.notification.createMany({
        data: members.map((m) => ({
          userId: m.userId,
          type: 'EXPENSE_CREATED' as const,
          data: {
            expenseId: exp.id,
            groupId,
            description: input.description,
            amountCents: input.amountCents,
            createdBy: userId,
          },
        })),
      });
    }

    return exp;
  });

  return expense;
}

export async function updateExpense(userId: string, groupId: string, expenseId: string, input: UpdateExpenseInput) {
  await assertMembership(userId, groupId);

  const existing = await prisma.expense.findUnique({
    where: { id: expenseId },
    include: { shares: true },
  });

  if (!existing || existing.groupId !== groupId) {
    throw new NotFoundError('Expense not found');
  }

  if (existing.version !== input.version) {
    throw new ConflictError('Expense was modified by another user. Please refresh and retry.');
  }

  const shares = calculateShares(
    input.splitType as SplitType,
    input.amountCents,
    input.participants
  );

  const expense = await prisma.$transaction(async (tx) => {
    // Delete old shares
    await tx.expenseShare.deleteMany({ where: { expenseId } });

    // Update expense
    const exp = await tx.expense.update({
      where: { id: expenseId },
      data: {
        payerId: input.payerId,
        description: input.description,
        amountCents: input.amountCents,
        date: new Date(input.date),
        splitType: input.splitType as SplitType,
        version: { increment: 1 },
        shares: {
          create: input.participants.map((p) => ({
            userId: p.userId,
            amountCents: shares.get(p.userId) ?? 0,
            percentage: p.percentage ?? null,
          })),
        },
      },
      include: {
        shares: {
          include: { user: { select: { id: true, displayName: true } } },
        },
        payer: { select: { id: true, displayName: true } },
      },
    });

    // Create audit log
    await tx.auditLog.create({
      data: {
        expenseId,
        userId,
        action: 'edit',
        data: {
          previous: {
            description: existing.description,
            amountCents: existing.amountCents,
            splitType: existing.splitType,
            shares: existing.shares,
          },
          current: {
            description: input.description,
            amountCents: input.amountCents,
            splitType: input.splitType,
          },
        },
      },
    });

    return exp;
  });

  return expense;
}

export async function deleteExpense(userId: string, groupId: string, expenseId: string) {
  await assertMembership(userId, groupId);

  const existing = await prisma.expense.findUnique({
    where: { id: expenseId },
    include: { shares: true },
  });

  if (!existing || existing.groupId !== groupId) {
    throw new NotFoundError('Expense not found');
  }

  await prisma.$transaction(async (tx) => {
    // Create audit log before deletion
    await tx.auditLog.create({
      data: {
        expenseId,
        userId,
        action: 'delete',
        data: {
          description: existing.description,
          amountCents: existing.amountCents,
          splitType: existing.splitType,
          shares: existing.shares,
        },
      },
    });

    await tx.expense.delete({ where: { id: expenseId } });
  });
}

export async function listExpenses(userId: string, groupId: string, page: number = 1) {
  await assertMembership(userId, groupId);

  const pageSize = 20;
  const [expenses, total] = await Promise.all([
    prisma.expense.findMany({
      where: { groupId },
      include: {
        payer: { select: { id: true, displayName: true } },
        shares: {
          include: { user: { select: { id: true, displayName: true } } },
        },
      },
      orderBy: { date: 'desc' },
      skip: (page - 1) * pageSize,
      take: pageSize,
    }),
    prisma.expense.count({ where: { groupId } }),
  ]);

  return {
    expenses,
    pagination: {
      page,
      pageSize,
      total,
      totalPages: Math.ceil(total / pageSize),
    },
  };
}

export async function getExpense(userId: string, groupId: string, expenseId: string) {
  await assertMembership(userId, groupId);

  const expense = await prisma.expense.findUnique({
    where: { id: expenseId },
    include: {
      payer: { select: { id: true, displayName: true } },
      shares: {
        include: { user: { select: { id: true, displayName: true } } },
      },
    },
  });

  if (!expense || expense.groupId !== groupId) {
    throw new NotFoundError('Expense not found');
  }

  return expense;
}

import { PrismaClient } from '@prisma/client';
import { NotFoundError, ValidationError } from '../utils/errors.js';
import { assertMembership } from './groupService.js';
import type { CreateSettlementInput } from '../types/schemas.js';

const prisma = new PrismaClient();

export async function createSettlement(userId: string, groupId: string, input: CreateSettlementInput) {
  await assertMembership(userId, groupId);

  // Verify both payer and recipient are group members
  const members = await prisma.groupMember.findMany({
    where: { groupId, userId: { in: [input.payerId, input.recipientId] } },
  });
  if (members.length !== 2) {
    throw new ValidationError('Both payer and recipient must be group members');
  }

  if (input.payerId === input.recipientId) {
    throw new ValidationError('Payer and recipient must be different');
  }

  const settlement = await prisma.$transaction(async (tx) => {
    const s = await tx.settlement.create({
      data: {
        groupId,
        payerId: input.payerId,
        recipientId: input.recipientId,
        amountCents: input.amountCents,
      },
      include: {
        payer: { select: { id: true, displayName: true } },
        recipient: { select: { id: true, displayName: true } },
      },
    });

    // Notify both parties (if they're not the one recording)
    const notifyUserIds = [input.payerId, input.recipientId].filter((id) => id !== userId);
    if (notifyUserIds.length > 0) {
      await tx.notification.createMany({
        data: notifyUserIds.map((uid) => ({
          userId: uid,
          type: 'SETTLEMENT_RECORDED' as const,
          data: {
            settlementId: s.id,
            groupId,
            amountCents: input.amountCents,
            payerId: input.payerId,
            recipientId: input.recipientId,
          },
        })),
      });
    }

    return s;
  });

  return settlement;
}

export async function listSettlements(userId: string, groupId: string) {
  await assertMembership(userId, groupId);

  const settlements = await prisma.settlement.findMany({
    where: { groupId },
    include: {
      payer: { select: { id: true, displayName: true } },
      recipient: { select: { id: true, displayName: true } },
    },
    orderBy: { createdAt: 'desc' },
  });

  return settlements;
}

