import { describe, it, expect } from 'vitest';
import { splitEqual, splitPercentage, splitFixed } from '../../src/utils/money.js';

describe('splitEqual', () => {
  it('splits evenly when divisible', () => {
    const result = splitEqual(3000, [
      { userId: 'a' },
      { userId: 'b' },
      { userId: 'c' },
    ]);
    expect(result.get('a')).toBe(1000);
    expect(result.get('b')).toBe(1000);
    expect(result.get('c')).toBe(1000);
  });

  it('distributes remainder cents to first participants', () => {
    const result = splitEqual(1000, [
      { userId: 'a' },
      { userId: 'b' },
      { userId: 'c' },
    ]);
    // 1000 / 3 = 333 remainder 1
    expect(result.get('a')).toBe(334);
    expect(result.get('b')).toBe(333);
    expect(result.get('c')).toBe(333);
    // Sum should be exact
    expect((result.get('a') ?? 0) + (result.get('b') ?? 0) + (result.get('c') ?? 0)).toBe(1000);
  });

  it('handles single participant', () => {
    const result = splitEqual(5000, [{ userId: 'a' }]);
    expect(result.get('a')).toBe(5000);
  });
});

describe('splitPercentage', () => {
  it('splits by percentage correctly', () => {
    const result = splitPercentage(10000, [
      { userId: 'a', percentage: 50 },
      { userId: 'b', percentage: 30 },
      { userId: 'c', percentage: 20 },
    ]);
    expect(result.get('a')).toBe(5000);
    expect(result.get('b')).toBe(3000);
    expect(result.get('c')).toBe(2000);
  });

  it('throws when percentages do not sum to 100', () => {
    expect(() =>
      splitPercentage(10000, [
        { userId: 'a', percentage: 50 },
        { userId: 'b', percentage: 30 },
      ])
    ).toThrow('Percentages must sum to 100%');
  });

  it('handles rounding remainder correctly', () => {
    const result = splitPercentage(1000, [
      { userId: 'a', percentage: 33.33 },
      { userId: 'b', percentage: 33.33 },
      { userId: 'c', percentage: 33.34 },
    ]);
    const sum = (result.get('a') ?? 0) + (result.get('b') ?? 0) + (result.get('c') ?? 0);
    expect(sum).toBe(1000);
  });
});

describe('splitFixed', () => {
  it('splits by fixed amounts', () => {
    const result = splitFixed(5000, [
      { userId: 'a', amountCents: 2000 },
      { userId: 'b', amountCents: 3000 },
    ]);
    expect(result.get('a')).toBe(2000);
    expect(result.get('b')).toBe(3000);
  });

  it('throws when fixed amounts do not sum to total', () => {
    expect(() =>
      splitFixed(5000, [
        { userId: 'a', amountCents: 2000 },
        { userId: 'b', amountCents: 2000 },
      ])
    ).toThrow('Fixed amounts must sum to the total expense amount');
  });
});

