 20→export async function getBalances(userId: string, groupId: string): Promise<Balance[]> {
 21→  await assertMembership(userId, groupId);
 22→
 23→  const members = await prisma.groupMember.findMany({
 24→    where: { groupId },
 25→    include: { user: { select: { id: true, displayName: true } } },
 26→  });
 27→
 28→  const expenses = await prisma.expense.findMany({
 29→    where: { groupId },
 30→    include: { shares: true },
 31→  });
 32→
 33→  const settlements = await prisma.settlement.findMany({
 34→    where: { groupId },
 35→  });
 36→
 37→  // Calculate net balances: positive = owed money, negative = owes money
 38→  const balanceMap = new Map<string, number>();
 39→  members.forEach((m) => balanceMap.set(m.userId, 0));
 40→
 41→  for (const expense of expenses) {
 42→    // Payer is owed the full amount
 43→    balanceMap.set(expense.payerId, (balanceMap.get(expense.payerId) ?? 0) + expense.amountCents);
 44→    // Each participant owes their share
 45→    for (const share of expense.shares) {
 46→      balanceMap.set(share.userId, (balanceMap.get(share.userId) ?? 0) - share.amountCents);
 47→    }
 48→  }
 49→
 50→  // Settlements: payer reduces their debt, recipient reduces what they're owed
 51→  for (const settlement of settlements) {
 52→    balanceMap.set(settlement.payerId, (balanceMap.get(settlement.payerId) ?? 0) + settlement.amountCents);
 53→    balanceMap.set(settlement.recipientId, (balanceMap.get(settlement.recipientId) ?? 0) - settlement.amountCents);
 54→  }
 55→
 56→  const memberMap = new Map(members.map((m) => [m.userId, m.user.displayName]));
 57→
 58→  return members.map((m) => ({
 59→    userId: m.userId,
 60→    displayName: memberMap.get(m.userId) ?? 'Unknown',
 61→    balanceCents: balanceMap.get(m.userId) ?? 0,
 62→  }));
 63→}
