119→    select: { id: true, paypalLink: true },
120→  });
121→  const paypalMap = new Map(users.map((u) => [u.id, u.paypalLink]));
122→
123→  return debts.map((d) => ({
124→    ...d,
125→    recipientPaypalLink: paypalMap.get(d.toUserId) ?? null,
126→  }));
127→}
