  1→import bcrypt from 'bcryptjs';
  2→import jwt from 'jsonwebtoken';
  3→import { PrismaClient } from '@prisma/client';
  4→import { config } from '../config/index.js';
  5→import { ConflictError, UnauthorizedError } from '../utils/errors.js';
  6→import type { RegisterInput, LoginInput } from '../types/schemas.js';
  7→
  8→const prisma = new PrismaClient();
  9→
 10→const BCRYPT_ROUNDS = 12;
 11→const ACCESS_TOKEN_EXPIRY = '15m';
 12→const REFRESH_TOKEN_EXPIRY = '7d';
 13→
 14→export interface TokenPayload {
 15→  userId: string;
 16→  email: string;
 17→}
 18→
 19→function generateAccessToken(payload: TokenPayload): string {
 20→  return jwt.sign(payload, config.JWT_SECRET, {
 21→    expiresIn: ACCESS_TOKEN_EXPIRY,
 22→  });
 23→}
 24→
 25→function generateRefreshToken(payload: TokenPayload): string {
 26→  return jwt.sign(payload, config.JWT_REFRESH_SECRET, {
 27→    expiresIn: REFRESH_TOKEN_EXPIRY,
 28→  });
 29→}
 30→
 31→export function verifyAccessToken(token: string): TokenPayload {
 32→  return jwt.verify(token, config.JWT_SECRET) as TokenPayload;
 33→}
 34→
 35→export function verifyRefreshToken(token: string): TokenPayload {
 36→  return jwt.verify(token, config.JWT_REFRESH_SECRET) as TokenPayload;
 37→}
 38→
 39→export async function register(input: RegisterInput) {
 40→  const existing = await prisma.user.findUnique({
 41→    where: { email: input.email },
 42→  });
 43→  if (existing) {
 44→    throw new ConflictError('Email already in use');
 45→  }
 46→
 47→  const hashedPassword = await bcrypt.hash(input.password, BCRYPT_ROUNDS);
 48→
 49→  const user = await prisma.user.create({
 50→    data: {
 51→      email: input.email,
 52→      password: hashedPassword,
 53→      displayName: input.displayName,
 54→    },
 55→  });
 56→
 57→  const payload: TokenPayload = { userId: user.id, email: user.email };
 58→  const accessToken = generateAccessToken(payload);
 59→  const refreshToken = generateRefreshToken(payload);
 60→
 61→  return {
 62→    user: {
 63→      id: user.id,
 64→      email: user.email,
 65→      displayName: user.displayName,
 66→      paypalLink: user.paypalLink,
 67→    },
 68→    accessToken,
 69→    refreshToken,
 70→  };
 71→}
 72→
 73→export async function login(input: LoginInput) {
 74→  const user = await prisma.user.findUnique({
 75→    where: { email: input.email },
 76→  });
 77→
 78→  if (!user) {
 79→    throw new UnauthorizedError('Invalid email or password');
 80→  }
 81→
 82→  const valid = await bcrypt.compare(input.password, user.password);
 83→  if (!valid) {
 84→    throw new UnauthorizedError('Invalid email or password');
 85→  }
 86→
 87→  const payload: TokenPayload = { userId: user.id, email: user.email };
 88→  const accessToken = generateAccessToken(payload);
 89→  const refreshToken = generateRefreshToken(payload);
 90→
 91→  return {
 92→    user: {
 93→      id: user.id,
 94→      email: user.email,
 95→      displayName: user.displayName,
 96→      paypalLink: user.paypalLink,
 97→    },
 98→    accessToken,
 99→    refreshToken,
100→  };
101→}
102→
103→export async function refreshTokens(currentRefreshToken: string) {
104→  const payload = verifyRefreshToken(currentRefreshToken);
105→
106→  const user = await prisma.user.findUnique({
107→    where: { id: payload.userId },
108→  });
109→
110→  if (!user) {
111→    throw new UnauthorizedError('User not found');
112→  }
113→
114→  const newPayload: TokenPayload = { userId: user.id, email: user.email };
115→  const accessToken = generateAccessToken(newPayload);
116→  const refreshToken = generateRefreshToken(newPayload);
117→
118→  return { accessToken, refreshToken };
119→}
