  1→import { PrismaClient, SplitType } from '@prisma/client';
  2→import { ConflictError, NotFoundError } from '../utils/errors.js';
  3→import { splitEqual, splitPercentage, splitFixed, type SplitParticipant } from '../utils/money.js';
  4→import { assertMembership } from './groupService.js';
  5→import type { CreateExpenseInput, UpdateExpenseInput } from '../types/schemas.js';
  6→
  7→const prisma = new PrismaClient();
  8→
  9→function calculateShares(
 10→  splitType: SplitType,
 11→  amountCents: number,
 12→  participants: SplitParticipant[]
 13→): Map<string, number> {
 14→  switch (splitType) {
 15→    case 'EQUAL':
 16→      return splitEqual(amountCents, participants);
 17→    case 'PERCENTAGE':
 18→      return splitPercentage(amountCents, participants);
 19→    case 'FIXED':
 20→      return splitFixed(amountCents, participants);
 21→  }
 22→}
 23→
 24→export async function createExpense(userId: string, groupId: string, input: CreateExpenseInput) {
 25→  await assertMembership(userId, groupId);
 26→
 27→  const shares = calculateShares(
 28→    input.splitType as SplitType,
 29→    input.amountCents,
 30→    input.participants
 31→  );
 32→
 33→  const expense = await prisma.$transaction(async (tx) => {
 34→    const exp = await tx.expense.create({
 35→      data: {
 36→        groupId,
 37→        payerId: input.payerId,
 38→        description: input.description,
 39→        amountCents: input.amountCents,
 40→        date: new Date(input.date),
 41→        splitType: input.splitType as SplitType,
 42→        shares: {
 43→          create: input.participants.map((p) => ({
 44→            userId: p.userId,
 45→            amountCents: shares.get(p.userId) ?? 0,
 46→            percentage: p.percentage ?? null,
 47→          })),
 48→        },
 49→      },
 50→      include: {
 51→        shares: {
 52→          include: { user: { select: { id: true, displayName: true } } },
 53→        },
 54→        payer: { select: { id: true, displayName: true } },
 55→      },
 56→    });
 57→
 58→    // Create notifications for group members except the creator
 59→    const members = await tx.groupMember.findMany({
 60→      where: { groupId, userId: { not: userId } },
 61→    });
 62→
 63→    if (members.length > 0) {
 64→      await tx.notification.createMany({
 65→        data: members.map((m) => ({
 66→          userId: m.userId,
 67→          type: 'EXPENSE_CREATED' as const,
 68→          data: {
 69→            expenseId: exp.id,
 70→            groupId,
 71→            description: input.description,
 72→            amountCents: input.amountCents,
 73→            createdBy: userId,
 74→          },
 75→        })),
 76→      });
 77→    }
 78→
 79→    return exp;
 80→  });
 81→
 82→  return expense;
 83→}
 84→
 85→export async function updateExpense(userId: string, groupId: string, expenseId: string, input: UpdateExpenseInput) {
 86→  await assertMembership(userId, groupId);
 87→
 88→  const existing = await prisma.expense.findUnique({
 89→    where: { id: expenseId },
 90→    include: { shares: true },
 91→  });
 92→
 93→  if (!existing || existing.groupId !== groupId) {
 94→    throw new NotFoundError('Expense not found');
 95→  }
 96→
 97→  if (existing.version !== input.version) {
 98→    throw new ConflictError('Expense was modified by another user. Please refresh and retry.');
 99→  }
100→
101→  const shares = calculateShares(
102→    input.splitType as SplitType,
103→    input.amountCents,
104→    input.participants
105→  );
106→
107→  const expense = await prisma.$transaction(async (tx) => {
108→    // Delete old shares
109→    await tx.expenseShare.deleteMany({ where: { expenseId } });
110→
111→    // Update expense
112→    const exp = await tx.expense.update({
113→      where: { id: expenseId },
114→      data: {
115→        payerId: input.payerId,
116→        description: input.description,
117→        amountCents: input.amountCents,
118→        date: new Date(input.date),
119→        splitType: input.splitType as SplitType,
120→        version: { increment: 1 },
121→        shares: {
122→          create: input.participants.map((p) => ({
123→            userId: p.userId,
124→            amountCents: shares.get(p.userId) ?? 0,
125→            percentage: p.percentage ?? null,
126→          })),
127→        },
128→      },
129→      include: {
130→        shares: {
131→          include: { user: { select: { id: true, displayName: true } } },
132→        },
133→        payer: { select: { id: true, displayName: true } },
134→      },
135→    });
136→
137→    // Create audit log
138→    await tx.auditLog.create({
139→      data: {
140→        expenseId,
141→        userId,
142→        action: 'edit',
143→        data: {
144→          previous: {
145→            description: existing.description,
146→            amountCents: existing.amountCents,
147→            splitType: existing.splitType,
148→            shares: existing.shares,
149→          },
150→          current: {
151→            description: input.description,
152→            amountCents: input.amountCents,
153→            splitType: input.splitType,
154→          },
155→        },
156→      },
157→    });
158→
159→    return exp;
160→  });
161→
162→  return expense;
163→}
164→
165→export async function deleteExpense(userId: string, groupId: string, expenseId: string) {
166→  await assertMembership(userId, groupId);
167→
168→  const existing = await prisma.expense.findUnique({
169→    where: { id: expenseId },
170→    include: { shares: true },
171→  });
172→
173→  if (!existing || existing.groupId !== groupId) {
174→    throw new NotFoundError('Expense not found');
175→  }
176→
177→  await prisma.$transaction(async (tx) => {
178→    // Create audit log before deletion
179→    await tx.auditLog.create({
180→      data: {
181→        expenseId,
182→        userId,
183→        action: 'delete',
184→        data: {
185→          description: existing.description,
186→          amountCents: existing.amountCents,
187→          splitType: existing.splitType,
188→          shares: existing.shares,
189→        },
190→      },
191→    });
192→
193→    await tx.expense.delete({ where: { id: expenseId } });
194→  });
195→}
196→
197→export async function listExpenses(userId: string, groupId: string, page: number = 1) {
198→  await assertMembership(userId, groupId);
199→
200→  const pageSize = 20;
201→  const [expenses, total] = await Promise.all([
202→    prisma.expense.findMany({
203→      where: { groupId },
204→      include: {
205→        payer: { select: { id: true, displayName: true } },
206→        shares: {
207→          include: { user: { select: { id: true, displayName: true } } },
208→        },
209→      },
210→      orderBy: { date: 'desc' },
211→      skip: (page - 1) * pageSize,
212→      take: pageSize,
213→    }),
214→    prisma.expense.count({ where: { groupId } }),
215→  ]);
216→
217→  return {
218→    expenses,
219→    pagination: {
220→      page,
221→      pageSize,
222→      total,
223→      totalPages: Math.ceil(total / pageSize),
224→    },
225→  };
226→}
