228→export async function getExpense(userId: string, groupId: string, expenseId: string) {
229→  await assertMembership(userId, groupId);
230→
231→  const expense = await prisma.expense.findUnique({
232→    where: { id: expenseId },
233→    include: {
234→      payer: { select: { id: true, displayName: true } },
235→      shares: {
236→        include: { user: { select: { id: true, displayName: true } } },
237→      },
238→    },
239→  });
240→
241→  if (!expense || expense.groupId !== groupId) {
242→    throw new NotFoundError('Expense not found');
243→  }
244→
245→  return expense;
246→}
