  1→import { PrismaClient } from '@prisma/client';
  2→import { assertMembership } from './groupService.js';
  3→
  4→const prisma = new PrismaClient();
  5→
  6→interface Balance {
  7→  userId: string;
  8→  displayName: string;
  9→  balanceCents: number;
 10→}
 11→
 12→interface Debt {
 13→  fromUserId: string;
 14→  fromDisplayName: string;
 15→  toUserId: string;
 16→  toDisplayName: string;
 17→  amountCents: number;
 18→}
 19→
 20→export async function getBalances(userId: string, groupId: string): Promise<Balance[]> {
 21→  await assertMembership(userId, groupId);
 22→
 23→  const members = await prisma.groupMember.findMany({
 24→    where: { groupId },
 25→    include: { user: { select: { id: true, displayName: true } } },
 26→  });
 27→
 28→  const expenses = await prisma.expense.findMany({
 29→    where: { groupId },
 30→    include: { shares: true },
 31→  });
 32→
 33→  const settlements = await prisma.settlement.findMany({
 34→    where: { groupId },
 35→  });
 36→
 37→  // Calculate net balances: positive = owed money, negative = owes money
 38→  const balanceMap = new Map<string, number>();
 39→  members.forEach((m) => balanceMap.set(m.userId, 0));
 40→
 41→  for (const expense of expenses) {
 42→    // Payer is owed the full amount
 43→    balanceMap.set(expense.payerId, (balanceMap.get(expense.payerId) ?? 0) + expense.amountCents);
 44→    // Each participant owes their share
 45→    for (const share of expense.shares) {
 46→      balanceMap.set(share.userId, (balanceMap.get(share.userId) ?? 0) - share.amountCents);
 47→    }
 48→  }
 49→
 50→  // Settlements: payer reduces their debt, recipient reduces what they're owed
 51→  for (const settlement of settlements) {
 52→    balanceMap.set(settlement.payerId, (balanceMap.get(settlement.payerId) ?? 0) + settlement.amountCents);
 53→    balanceMap.set(settlement.recipientId, (balanceMap.get(settlement.recipientId) ?? 0) - settlement.amountCents);
 54→  }
 55→
 56→  const memberMap = new Map(members.map((m) => [m.userId, m.user.displayName]));
 57→
 58→  return members.map((m) => ({
 59→    userId: m.userId,
 60→    displayName: memberMap.get(m.userId) ?? 'Unknown',
 61→    balanceCents: balanceMap.get(m.userId) ?? 0,
 62→  }));
 63→}
 64→
 65→export async function getDebts(userId: string, groupId: string): Promise<Debt[]> {
 66→  const balances = await getBalances(userId, groupId);
 67→
 68→  // Separate debtors (negative balance) and creditors (positive balance)
 69→  const debtors = balances.filter((b) => b.balanceCents < 0).map((b) => ({ ...b }));
 70→  const creditors = balances.filter((b) => b.balanceCents > 0).map((b) => ({ ...b }));
 71→
 72→  return minimizeSettlements(debtors, creditors);
 73→}
 74→
 75→function minimizeSettlements(
 76→  debtors: { userId: string; displayName: string; balanceCents: number }[],
 77→  creditors: { userId: string; displayName: string; balanceCents: number }[]
 78→): Debt[] {
 79→  // Sort debtors by debt ascending (most negative first), creditors by credit descending
 80→  debtors.sort((a, b) => a.balanceCents - b.balanceCents);
 81→  creditors.sort((a, b) => b.balanceCents - a.balanceCents);
 82→
 83→  const debts: Debt[] = [];
 84→  let i = 0;
 85→  let j = 0;
 86→
 87→  while (i < debtors.length && j < creditors.length) {
 88→    const debtAmount = Math.abs(debtors[i].balanceCents);
 89→    const creditAmount = creditors[j].balanceCents;
 90→    const settleAmount = Math.min(debtAmount, creditAmount);
 91→
 92→    if (settleAmount > 0) {
 93→      debts.push({
 94→        fromUserId: debtors[i].userId,
 95→        fromDisplayName: debtors[i].displayName,
 96→        toUserId: creditors[j].userId,
 97→        toDisplayName: creditors[j].displayName,
 98→        amountCents: settleAmount,
 99→      });
100→    }
101→
102→    debtors[i].balanceCents += settleAmount;
103→    creditors[j].balanceCents -= settleAmount;
104→
105→    if (debtors[i].balanceCents === 0) i++;
106→    if (creditors[j].balanceCents === 0) j++;
107→  }
108→
109→  return debts;
110→}
111→
112→export async function getSettlementSuggestions(userId: string, groupId: string) {
113→  const debts = await getDebts(userId, groupId);
114→
115→  // Fetch PayPal links for recipients
116→  const recipientIds = [...new Set(debts.map((d) => d.toUserId))];
117→  const users = await prisma.user.findMany({
118→    where: { id: { in: recipientIds } },
119→    select: { id: true, paypalLink: true },
120→  });
121→  const paypalMap = new Map(users.map((u) => [u.id, u.paypalLink]));
122→
123→  return debts.map((d) => ({
124→    ...d,
125→    recipientPaypalLink: paypalMap.get(d.toUserId) ?? null,
126→  }));
127→}
