 1→import { ValidationError } from './errors.js';
 2→
 3→export interface SplitParticipant {
 4→  userId: string;
 5→  percentage?: number;
 6→  amountCents?: number;
 7→}
 8→
 9→export function splitEqual(totalCents: number, participants: SplitParticipant[]): Map<string, number> {
10→  const count = participants.length;
11→  const baseCents = Math.floor(totalCents / count);
12→  const remainder = totalCents - baseCents * count;
13→
14→  const result = new Map<string, number>();
15→  participants.forEach((p, i) => {
16→    result.set(p.userId, baseCents + (i < remainder ? 1 : 0));
17→  });
18→  return result;
19→}
20→
21→export function splitPercentage(totalCents: number, participants: SplitParticipant[]): Map<string, number> {
22→  const totalPct = participants.reduce((sum, p) => sum + (p.percentage ?? 0), 0);
23→  if (Math.abs(totalPct - 100) > 0.01) {
24→    throw new ValidationError('Percentages must sum to 100%');
25→  }
26→
27→  const result = new Map<string, number>();
28→  let allocated = 0;
29→
30→  participants.forEach((p, i) => {
31→    if (i === participants.length - 1) {
32→      // Last participant gets the remainder to ensure exact total
33→      result.set(p.userId, totalCents - allocated);
34→    } else {
35→      const share = Math.round((totalCents * (p.percentage ?? 0)) / 100);
36→      result.set(p.userId, share);
37→      allocated += share;
38→    }
39→  });
40→
41→  return result;
42→}
43→
44→export function splitFixed(totalCents: number, participants: SplitParticipant[]): Map<string, number> {
45→  const totalFixed = participants.reduce((sum, p) => sum + (p.amountCents ?? 0), 0);
46→  if (totalFixed !== totalCents) {
47→    throw new ValidationError('Fixed amounts must sum to the total expense amount');
48→  }
49→
50→  const result = new Map<string, number>();
51→  participants.forEach((p) => {
52→    result.set(p.userId, p.amountCents ?? 0);
53→  });
54→  return result;
55→}
56→
57→export function formatCents(cents: number): string {
58→  const dollars = cents / 100;
59→  return dollars.toFixed(2);
60→}
