 1→import type { Request, Response, NextFunction } from 'express';
 2→import { ZodSchema, ZodError } from 'zod';
 3→import { ValidationError } from '../utils/errors.js';
 4→
 5→export function validate(schema: ZodSchema, source: 'body' | 'query' | 'params' = 'body') {
 6→  return (req: Request, _res: Response, next: NextFunction): void => {
 7→    const result = schema.safeParse(req[source]);
 8→    if (!result.success) {
 9→      const details = result.error.issues.map((issue: ZodError['issues'][number]) => ({
10→        field: issue.path.join('.'),
11→        message: issue.message,
12→      }));
13→      next(new ValidationError('Validation failed', details));
14→      return;
15→    }
16→    req[source] = result.data;
17→    next();
18→  };
19→}
