11→export function requireAuth(req: Request, _res: Response, next: NextFunction): void {
12→  const accessToken = req.cookies?.accessToken;
13→
14→  if (!accessToken) {
15→    next(new UnauthorizedError('Authentication required'));
16→    return;
17→  }
18→
19→  try {
20→    const payload = verifyAccessToken(accessToken);
21→    req.user = payload;
22→    next();
23→  } catch {
24→    next(new UnauthorizedError('Invalid or expired token'));
25→  }
26→}
