28→export function setTokenCookies(
29→  res: Response,
30→  accessToken: string,
31→  refreshToken: string
32→): void {
33→  res.cookie('accessToken', accessToken, {
34→    httpOnly: true,
35→    secure: process.env.NODE_ENV === 'production',
36→    sameSite: 'strict',
37→    maxAge: 15 * 60 * 1000, // 15 minutes
38→  });
39→
40→  res.cookie('refreshToken', refreshToken, {
41→    httpOnly: true,
42→    secure: process.env.NODE_ENV === 'production',
43→    sameSite: 'strict',
44→    maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
45→  });
46→}
47→
48→export function clearTokenCookies(res: Response): void {
49→  res.clearCookie('accessToken');
50→  res.clearCookie('refreshToken');
