 5→export function errorHandler(
 6→  err: Error,
 7→  _req: Request,
 8→  res: Response,
 9→  _next: NextFunction
10→): void {
11→  if (err instanceof AppError) {
12→    res.status(err.statusCode).json({
13→      error: {
14→        code: err.code,
15→        message: err.message,
16→        ...(err.details && { details: err.details }),
17→      },
18→    });
