 81→
 82→  // Check if already a member
 83→  const existingMember = await prisma.groupMember.findFirst({
 84→    where: {
 85→      groupId,
 86→      user: { email },
 87→    },
 88→  });
 89→  if (existingMember) {
 90→    throw new ConflictError('User is already a member of this group');
 91→  }
 92→
 93→  // Check for pending invitation
 94→  const existingInvite = await prisma.invitation.findFirst({
 95→    where: {
 96→      groupId,
 97→      email,
 98→      status: 'PENDING',
 99→    },
100→  });
101→  if (existingInvite) {
102→    throw new ConflictError('An invitation is already pending for this email');
103→  }
104→
105→  // Find recipient user if they exist
106→  const recipientUser = await prisma.user.findUnique({ where: { email } });
107→
108→  const invitation = await prisma.$transaction(async (tx) => {
109→    const invite = await tx.invitation.create({
110→      data: {
111→        groupId,
112→        email,
113→        senderId: userId,
114→        recipientId: recipientUser?.id ?? null,
115→      },
116→    });
117→
118→    // Create in-app notification if the user exists
119→    if (recipientUser) {
120→      const group = await tx.group.findUnique({ where: { id: groupId }, select: { name: true } });
121→      const sender = await tx.user.findUnique({ where: { id: userId }, select: { displayName: true } });
122→      await tx.notification.create({
123→        data: {
124→          userId: recipientUser.id,
125→          type: 'GROUP_INVITATION',
126→          data: {
127→            invitationId: invite.id,
128→            groupId,
129→            groupName: group!.name,
130→            invitedBy: sender!.displayName,
131→          },
132→        },
133→      });
134→    }
135→
136→    return invite;
137→  });
138→
139→  return invitation;
140→}
