157→export async function respondToInvitation(userId: string, invitationId: string, accept: boolean) {
158→  const invitation = await prisma.invitation.findUnique({
159→    where: { id: invitationId },
160→  });
161→
162→  if (!invitation || invitation.recipientId !== userId) {
163→    throw new NotFoundError('Invitation not found');
164→  }
165→
166→  if (invitation.status !== 'PENDING') {
167→    throw new ConflictError('Invitation has already been responded to');
168→  }
169→
170→  if (accept) {
171→    await prisma.$transaction(async (tx) => {
172→      await tx.invitation.update({
173→        where: { id: invitationId },
174→        data: { status: 'ACCEPTED' },
175→      });
176→      await tx.groupMember.create({
177→        data: {
178→          userId,
179→          groupId: invitation.groupId,
180→        },
181→      });
182→    });
183→  } else {
184→    await prisma.invitation.update({
185→      where: { id: invitationId },
186→      data: { status: 'DECLINED' },
187→    });
188→  }
189→}
