 4→import type { CreateSettlementInput } from '../types/schemas.js';
 5→
 6→const prisma = new PrismaClient();
 7→
 8→export async function createSettlement(userId: string, groupId: string, input: CreateSettlementInput) {
 9→  await assertMembership(userId, groupId);
10→
11→  // Verify both payer and recipient are group members
12→  const members = await prisma.groupMember.findMany({
13→    where: { groupId, userId: { in: [input.payerId, input.recipientId] } },
14→  });
15→  if (members.length !== 2) {
16→    throw new ValidationError('Both payer and recipient must be group members');
17→  }
18→
19→  if (input.payerId === input.recipientId) {
20→    throw new ValidationError('Payer and recipient must be different');
21→  }
22→
23→  const settlement = await prisma.$transaction(async (tx) => {
24→    const s = await tx.settlement.create({
25→      data: {
26→        groupId,
27→        payerId: input.payerId,
28→        recipientId: input.recipientId,
29→        amountCents: input.amountCents,
30→      },
31→      include: {
32→        payer: { select: { id: true, displayName: true } },
33→        recipient: { select: { id: true, displayName: true } },
34→      },
35→    });
36→
37→    // Notify both parties (if they're not the one recording)
38→    const notifyUserIds = [input.payerId, input.recipientId].filter((id) => id !== userId);
39→    if (notifyUserIds.length > 0) {
40→      await tx.notification.createMany({
41→        data: notifyUserIds.map((uid) => ({
42→          userId: uid,
43→          type: 'SETTLEMENT_RECORDED' as const,
44→          data: {
45→            settlementId: s.id,
46→            groupId,
47→            amountCents: input.amountCents,
48→            payerId: input.payerId,
49→            recipientId: input.recipientId,
50→          },
51→        })),
52→      });
53→    }
54→
55→    return s;
56→  });
57→
58→  return settlement;
59→}
