 1→const API_BASE = '/api/v1';
 2→
 3→interface FetchOptions extends RequestInit {
 4→  body?: string;
 5→}
 6→
 7→export async function apiFetch<T>(
 8→  path: string,
 9→  options: FetchOptions = {}
10→): Promise<T> {
11→  const res = await fetch(`${API_BASE}${path}`, {
12→    ...options,
13→    credentials: 'include',
14→    headers: {
15→      'Content-Type': 'application/json',
16→      ...options.headers,
17→    },
18→  });
19→
20→  const json = await res.json();
21→
22→  if (!res.ok) {
23→    const errorMessage = json.error?.message || 'An error occurred';
24→    throw new ApiError(res.status, json.error?.code || 'UNKNOWN', errorMessage, json.error?.details);
25→  }
26→
27→  return json.data;
28→}
