 11→export default function CreateExpensePage() {
 12→  const { groupId } = useParams<{ groupId: string }>();
 13→  const navigate = useNavigate();
 14→  const { user } = useAuth();
 15→  const [members, setMembers] = useState<Member[]>([]);
 16→  const [description, setDescription] = useState('');
 17→  const [amount, setAmount] = useState('');
 18→  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
 19→  const [payerId, setPayerId] = useState(user?.id || '');
 20→  const [splitType, setSplitType] = useState<'EQUAL' | 'PERCENTAGE' | 'FIXED'>('EQUAL');
 21→  const [selectedParticipants, setSelectedParticipants] = useState<Set<string>>(new Set());
 22→  const [percentages, setPercentages] = useState<Record<string, string>>({});
 23→  const [fixedAmounts, setFixedAmounts] = useState<Record<string, string>>({});
 24→  const [error, setError] = useState('');
 25→  const [loading, setLoading] = useState(false);
 26→
 27→  useEffect(() => {
 28→    (async () => {
 29→      try {
 30→        const data = await apiFetch<Member[]>(`/groups/${groupId}/members`);
 31→        setMembers(data);
 32→        // Select all members by default
 33→        setSelectedParticipants(new Set(data.map((m) => m.user.id)));
 34→      } catch {
 35→        setError('Failed to load members');
 36→      }
 37→    })();
 38→  }, [groupId]);
 39→
 40→  const toggleParticipant = (userId: string) => {
 41→    setSelectedParticipants((prev) => {
 42→      const next = new Set(prev);
 43→      if (next.has(userId)) next.delete(userId);
 44→      else next.add(userId);
 45→      return next;
 46→    });
 47→  };
 48→
 49→  const handleSubmit = async (e: FormEvent) => {
 50→    e.preventDefault();
 51→    setError('');
 52→    setLoading(true);
 53→
 54→    const amountCents = Math.round(parseFloat(amount) * 100);
 55→    if (isNaN(amountCents) || amountCents <= 0) {
 56→      setError('Please enter a valid positive amount');
 57→      setLoading(false);
 58→      return;
 59→    }
 60→
 61→    if (selectedParticipants.size === 0) {
 62→      setError('At least one participant is required');
 63→      setLoading(false);
 64→      return;
 65→    }
 66→
 67→    const participants = Array.from(selectedParticipants).map((userId) => {
 68→      const p: { userId: string; percentage?: number; amountCents?: number } = { userId };
 69→      if (splitType === 'PERCENTAGE') {
 70→        p.percentage = parseFloat(percentages[userId] || '0');
 71→      } else if (splitType === 'FIXED') {
 72→        p.amountCents = Math.round(parseFloat(fixedAmounts[userId] || '0') * 100);
 73→      }
 74→      return p;
 75→    });
 76→
 77→    try {
 78→      await apiFetch(`/groups/${groupId}/expenses`, {
 79→        method: 'POST',
 80→        body: JSON.stringify({
 81→          description,
 82→          amountCents,
 83→          date,
 84→          payerId,
 85→          splitType,
 86→          participants,
 87→        }),
 88→      });
 89→      navigate(`/groups/${groupId}/expenses`);
 90→    } catch (err) {
 91→      setError(err instanceof ApiError ? err.message : 'Failed to create expense');
 92→    } finally {
 93→      setLoading(false);
 94→    }
 95→  };
 96→
 97→  return (
 98→    <div className="max-w-2xl mx-auto p-6">
 99→      <Link to={`/groups/${groupId}/expenses`} className="text-blue-600 hover:text-blue-500 text-sm mb-4 inline-block">&larr; Back to Expenses</Link>
100→      <h1 className="text-2xl font-bold text-gray-900 mb-6">Add Expense</h1>
101→
102→      {error && (
