104→      )}
105→
106→      <form onSubmit={handleSubmit} className="space-y-4 bg-white p-6 rounded-lg shadow">
107→        <div>
108→          <label htmlFor="description" className="block text-sm font-medium text-gray-700">Description</label>
109→          <input id="description" type="text" value={description} onChange={(e) => setDescription(e.target.value)} required
110→            className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500" />
111→        </div>
112→
113→        <div>
114→          <label htmlFor="amount" className="block text-sm font-medium text-gray-700">Amount ($)</label>
115→          <input id="amount" type="number" step="0.01" min="0.01" value={amount} onChange={(e) => setAmount(e.target.value)} required
116→            className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500" />
117→        </div>
118→
119→        <div>
120→          <label htmlFor="date" className="block text-sm font-medium text-gray-700">Date</label>
121→          <input id="date" type="date" value={date} onChange={(e) => setDate(e.target.value)} required
122→            className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500" />
123→        </div>
124→
125→        <div>
126→          <label htmlFor="payer" className="block text-sm font-medium text-gray-700">Paid by</label>
127→          <select id="payer" value={payerId} onChange={(e) => setPayerId(e.target.value)}
128→            className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500">
129→            {members.map((m) => (
130→              <option key={m.user.id} value={m.user.id}>{m.user.displayName}</option>
131→            ))}
132→          </select>
133→        </div>
134→
135→        <div>
136→          <label className="block text-sm font-medium text-gray-700 mb-2">Split Type</label>
137→          <div className="flex gap-4">
138→            {(['EQUAL', 'PERCENTAGE', 'FIXED'] as const).map((st) => (
139→              <label key={st} className="flex items-center gap-1">
140→                <input type="radio" name="splitType" value={st} checked={splitType === st} onChange={() => setSplitType(st)} />
141→                <span className="text-sm">{st.charAt(0) + st.slice(1).toLowerCase()}</span>
142→              </label>
