154→                  <span className="text-sm">{m.user.displayName}</span>
155→                </label>
156→                {splitType === 'PERCENTAGE' && selectedParticipants.has(m.user.id) && (
157→                  <input type="number" step="0.01" placeholder="%" value={percentages[m.user.id] || ''}
