  4→interface Notification {
  5→  id: string;
  6→  type: string;
  7→  data: Record<string, unknown>;
  8→  read: boolean;
  9→  createdAt: string;
 10→}
 11→
 12→function notificationMessage(n: Notification): string {
 13→  switch (n.type) {
 14→    case 'GROUP_INVITATION':
 15→      return `You were invited to ${(n.data as { groupName?: string }).groupName ?? 'a group'} by ${(n.data as { invitedBy?: string }).invitedBy ?? 'someone'}`;
 16→    case 'EXPENSE_CREATED':
 17→      return `New expense "${(n.data as { description?: string }).description ?? ''}" ($${((n.data as { amountCents?: number }).amountCents ?? 0) / 100}) added`;
 18→    case 'SETTLEMENT_RECORDED':
 19→      return `A settlement of $${((n.data as { amountCents?: number }).amountCents ?? 0) / 100} was recorded`;
 20→    default:
 21→      return 'New notification';
 22→  }
 23→}
 24→
 25→export default function NotificationsPage() {
 26→  const [notifications, setNotifications] = useState<Notification[]>([]);
 27→  const [loading, setLoading] = useState(true);
 28→
 29→  const loadNotifications = async () => {
 30→    try {
 31→      const data = await apiFetch<Notification[]>('/notifications');
 32→      setNotifications(data);
 33→    } catch {
 34→      // handle silently
 35→    } finally {
 36→      setLoading(false);
 37→    }
 38→  };
 39→
 40→  useEffect(() => {
 41→    loadNotifications();
 42→  }, []);
 43→
 44→  const markAsRead = async (id: string) => {
 45→    try {
 46→      await apiFetch(`/notifications/${id}/read`, { method: 'POST' });
 47→      setNotifications((prev) =>
 48→        prev.map((n) => (n.id === id ? { ...n, read: true } : n))
 49→      );
 50→    } catch {
 51→      // handle silently
 52→    }
 53→  };
 54→
 55→  const markAllRead = async () => {
 56→    try {
 57→      await apiFetch('/notifications/read-all', { method: 'POST' });
 58→      setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
 59→    } catch {
 60→      // handle silently
 61→    }
 62→  };
 63→
 64→  if (loading) return <div className="max-w-4xl mx-auto p-6">Loading...</div>;
 65→
 66→  const unreadCount = notifications.filter((n) => !n.read).length;
 67→
 68→  return (
 69→    <div className="max-w-4xl mx-auto p-6">
 70→      <div className="flex justify-between items-center mb-6">
 71→        <h1 className="text-2xl font-bold text-gray-900">
