 73→          {unreadCount > 0 && (
 74→            <span className="ml-2 text-sm bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full">{unreadCount} unread</span>
 75→          )}
 76→        </h1>
 77→        {unreadCount > 0 && (
 78→          <button onClick={markAllRead} className="text-sm text-blue-600 hover:text-blue-500">
 79→            Mark all as read
 80→          </button>
 81→        )}
 82→      </div>
 83→
 84→      {notifications.length === 0 ? (
 85→        <p className="text-gray-600">No notifications.</p>
 86→      ) : (
 87→        <div className="space-y-2">
 88→          {notifications.map((n) => (
 89→            <div
