 3→
 4→interface UseApiState<T> {
 5→  data: T | null;
 6→  error: ApiError | null;
 7→  loading: boolean;
 8→}
 9→
10→export function useApi<T>() {
11→  const [state, setState] = useState<UseApiState<T>>({
12→    data: null,
13→    error: null,
14→    loading: false,
15→  });
16→
17→  const execute = useCallback(
18→    async (path: string, options?: { method?: string; body?: string; headers?: Record<string, string> }): Promise<T | null> => {
